/** Either the artifact directory name, or anything carrying one — a mount declaration, say. */
export type ArtifactRef = string | { artifact: string };

/**
 * The emitted template, as the artifact module states it, and the two things
 * the same artifacts say about what the build did NOT write into it: the keyed
 * regions whose items belong to a store that does not exist yet, and the
 * bindings whose text a captured paint measures.
 *
 * Both belong here rather than in a second reader because both are read for the
 * same reason — deciding what a mount's markup is owed, and by whom — and a
 * caller that had to ask twice would be a caller that could ask once and get
 * half an answer.
 */
export interface EmittedTemplate {
  html: string;
  root: string;
  /** The keyed regions the component declares. Any at all makes its mount a carried one. */
  regions: CarriedRegion[];
  /** Locators of the bindings whose text is measured rather than folded at build time. */
  measured: string[];
}

function keyOf(ref: ArtifactRef): string {
  return typeof ref === 'string' ? ref : ref.artifact;
}

/** Where one component's artifacts live under `artifactRoot`. */
export function artifactDir(artifactRoot: string, ref: ArtifactRef): string {
  return join(artifactRoot, keyOf(ref));
}

/** The emitted manifest, parsed. */
export function readManifest<T = unknown>(artifactRoot: string, ref: ArtifactRef): T {
  return JSON.parse(readFileSync(join(artifactDir(artifactRoot, ref), 'manifest.json'), 'utf8')) as T;
}

/**
 * The emitted markup, read out of the artifact module itself rather than out
 * of the manifest — it is the module the build inlines, so it is the module
 * the build should read. The cache-busting query is what makes a re-emit
 * visible to a process that already imported the old one.
 */
export async function readTemplate(
  artifactRoot: string,
  ref: ArtifactRef,
): Promise<EmittedTemplate> {
  const directory = artifactDir(artifactRoot, ref);
  const url = pathToFileURL(join(directory, 'template.js')).href;
  const module = (await import(`${url}?t=${Date.now()}`)) as { html: string; root: string };
  return { html: module.html, root: module.root, ...(await readEmittedShape(directory)) };
}

/** One emitted binding, as far as "did the build write this text" goes. */
interface EmittedBinding {
  locator: string;
  initialTextFrom?: string;
}

/**
 * What the emitted `structure.js` says about the bytes the build left to
 * someone else — read out of the same module the resume path reads them from,
 * rather than out of the manifest beside it, so a page is checked against the
 * record the page itself runs on.
 *
 * An artifact emitted before regions existed says neither, and gets the empty
 * answer that means "this mount is the pass's to fill".
 */
async function readEmittedShape(
  directory: string,
): Promise<{ regions: CarriedRegion[]; measured: string[] }> {
  const path = join(directory, 'structure.js');
  if (!existsSync(path)) return { regions: [], measured: [] };

  const url = pathToFileURL(path).href;
  const structure = (await import(`${url}?t=${Date.now()}`)) as {
    keyedRegions?: CarriedRegion[];
    bindings?: EmittedBinding[];
  };

  return {
    regions: (structure.keyedRegions ?? []).map((region) => ({
      id: region.id,
      container: region.container,
      keyAttribute: region.keyAttribute,
    })),
    measured: (structure.bindings ?? [])
      .filter((binding) => binding.initialTextFrom === 'capture')
      .map((binding) => binding.locator),
  };
}

/**
 * Normalization and refusal.
 *
 * Every stage downstream reads `ResolvedOptions` and nothing else: absolute
 * paths, no optionals, no defaults left to be applied twice in two places by
 * two people who disagree. Everything a stage would otherwise have to guess is
 * decided here, once, at construction time.
 *
 * The refusals are the more interesting half. A build tool that silently
 * accepts a configuration it cannot honour spends the user's afternoon; each
 * refusal below throws before a single file is read, carries its own error
 * name so a caller can branch on it, and says what to do instead.
 */

import { existsSync } from 'node:fs';
import { dirname, isAbsolute, join, relative, resolve } from 'pathe';

import { artifactKey } from '../../src/comptime/index.ts';
import type {
  MountDeclaration,
  PageDeclaration,
  ResolvedMount,
  ResolvedOptions,
  ResolvedPage,
  ResolvedPageFallback,
  ResolvedPolicies,
  ResolvedSubstitution,
  ResumabilityOptions,
} from './types.ts';

/**
 * A configuration the plugin will not act on.
 *
 * `name` is the refusal's own name rather than the class's, so a test or a
 * caller can assert which rule fired without matching on prose that may be
 * reworded.
 */
export class ResumabilityConfigError extends Error {
  constructor(name: RefusalName, message: string) {
    super(message);
    this.name = name;
  }
}

/** Every way this plugin declines a configuration. */
export type RefusalName =
  | 'NoMountsDeclared'
  | 'MountSourceMissing'
  | 'ArtifactKeyCollision'
  | 'DuplicatePageId'
  | 'MountPageUnknown'
  | 'PrerenderWithoutGroup'
  | 'PrefetchIdleRefused'
  | 'FallbackBranchUndeclared'
  | 'FallbackModuleMissing'
  | 'FallbackSpecifierMissing'
  | 'SubstituteOutMissing'
  | 'ClaimGlueUndeclared'
  | 'PageFeaturesUnsupported';

function refuse(name: RefusalName, message: string): never {
  throw new ResumabilityConfigError(name, message);
}

/** This package's own runtime, which is what an ordinary consumer wants. */
export const DEFAULT_RUNTIME_SPECIFIER = 'unplugin-solid-resumability/runtime';

const DEFAULT_POLICIES: ResolvedPolicies = {
  expectProvable: true,
  prefetch: 'interaction',
  fallback: 'always',
  pruneStaleArtifacts: true,
  chunking: true,
};

/**
 * Fills in every default and refuses everything unworkable.
 *
 * `bundlerRoot` is what the bundler believes the project root is; an explicit
 * `options.root` wins over it, and the process cwd is the last resort.
 */
export function resolveOptions(
  options: ResumabilityOptions,
  bundlerRoot?: string,
): ResolvedOptions {
  const root = resolve(options.root ?? bundlerRoot ?? process.cwd());
  const corpusRoot = absoluteUnder(root, options.corpusRoot ?? root);
  const artifactDir = absoluteUnder(root, options.artifactDir ?? join(root, 'artifacts'));
  const generatedDir = absoluteUnder(root, options.generatedDir ?? join(root, 'src/generated'));

  const policies = resolvePolicies(options.policies);
  const pages = resolvePages(options.pages ?? [], root, policies);
  const mounts = resolveMounts(options.mounts, root, generatedDir, policies, pages);

  return {
    root,
    corpusRoot,
    artifactDir,
    generatedDir,
    mounts,
    pages,
    policies,
    runtime: options.runtime ?? DEFAULT_RUNTIME_SPECIFIER,
    substitute: options.substitute ?? {},
  };
}

function resolvePolicies(declared: ResumabilityOptions['policies']): ResolvedPolicies {
  const policies = { ...DEFAULT_POLICIES, ...declared };

  // Stated as a refusal rather than left undocumented: a rejected policy that
  // is merely absent gets re-invented by the next person who reads the code.
  if ((policies.prefetch as string) === 'idle') {
    refuse(
      'PrefetchIdleRefused',
      "policies.prefetch: 'idle' is refused. An idle prefetch spends network on a group the " +
        'user may never open, which is the cost this pipeline exists to remove (zero-eager ' +
        "§4.5). Use 'interaction' to fetch on first touch, or 'none' to fetch only on demand.",
    );
  }

  return policies;
}

function resolvePages(
  declared: PageDeclaration[],
  root: string,
  policies: ResolvedPolicies,
): ResolvedPage[] {
  const seen = new Set<string>();

  // A policy that cannot act on anything is the worst kind of green: the build
  // reports the omission it was asked for and emits every byte it was asked to
  // drop. Said once, here, rather than per page — one page declaring a branch
  // is enough for the policy to mean something.
  if (policies.fallback === 'auto-omit' && !declared.some((page) => page.fallback !== undefined)) {
    refuse(
      'FallbackBranchUndeclared',
      "policies.fallback: 'auto-omit' is declared but no page says where its fallback branch " +
        'is. The derivation is the pass\'s (a page may omit the branch iff every mount declared ' +
        'against it is provable); WHICH module holds the branch and WHICH specifier reaches the ' +
        'ordinary renderer is yours. Declare `fallback: { module, specifier }` on the page that ' +
        "carries it, or use 'always'.",
    );
  }

  return declared.map((page) => {
    if (seen.has(page.id)) {
      refuse(
        'DuplicatePageId',
        `two pages declare the id ${JSON.stringify(page.id)}. Page ids address a page from a ` +
          'mount declaration, so they have to be unique.',
      );
    }
    seen.add(page.id);

    const prerender = page.prerender ?? false;
    const group = page.group ?? false;

    // Prerender captures the page by running its group in a headless DOM. With
    // no group there is nothing to run, so a page asking for both would sit
    // there capturing an empty shell and calling it a success.
    if (prerender !== false && group === false) {
      refuse(
        'PrerenderWithoutGroup',
        `page ${JSON.stringify(page.id)} declares prerender but no group. Prerendering runs the ` +
          'page\'s group module to capture its markup; declare `group`, or drop `prerender`.',
      );
    }

    return {
      id: page.id,
      html: page.html,
      htmlPath: absoluteUnder(root, page.html),
      entry: page.entry,
      inlineTemplates: page.inlineTemplates ?? false,
      prerender,
      group,
      fallback: resolveFallback(page, root),
    };
  });
}

/**
 * The declared fallback branch, made absolute and checked for existence.
 *
 * Checked here for the same reason a mount source is: a typo in the config
 * should read as a typo in the config, and not as a transform that quietly
 * matched nothing and left the branch in the build.
 */
function resolveFallback(page: PageDeclaration, root: string): ResolvedPageFallback | false {
  const declared = page.fallback;
  if (declared === undefined) return false;

  if (!declared.module) {
    refuse(
      'FallbackModuleMissing',
      `page ${JSON.stringify(page.id)} declares a fallback branch with no \`module\`. The branch ` +
        'is a dynamic import in one of your own modules; name the module that writes it.',
    );
  }

  if (!declared.specifier) {
    refuse(
      'FallbackSpecifierMissing',
      `page ${JSON.stringify(page.id)} declares a fallback branch with no \`specifier\`. Omission ` +
        'rewrites one `import()` and leaves every other import in that module alone, so it has ' +
        'to be told which one.',
    );
  }

  const modulePath = absoluteUnder(root, declared.module);
  if (!existsSync(modulePath)) {
    refuse(
      'FallbackModuleMissing',
      `page ${JSON.stringify(page.id)} declares its fallback branch in ` +
        `${JSON.stringify(declared.module)}, which does not exist (looked at ${modulePath}). ` +
        'Fallback modules are resolved against the project root.',
    );
  }

  return { module: declared.module, modulePath, specifier: declared.specifier };
}

function resolveMounts(
  declared: MountDeclaration[],
  root: string,
  generatedDir: string,
  policies: ResolvedPolicies,
  pages: ResolvedPage[],
): ResolvedMount[] {
  if (!declared || declared.length === 0) {
    refuse(
      'NoMountsDeclared',
      'no mounts declared. The mount list is the whole input to the pass: without it there is ' +
        'nothing to prove and nothing to emit.',
    );
  }

  const pageIds = new Set(pages.map((page) => page.id));
  const byArtifact = new Map<string, ResolvedMount>();

  return declared.map((mount) => {
    const sourcePath = absoluteUnder(root, mount.source);

    // Checked here rather than at the pass, so a typo in the config reads as a
    // typo in the config instead of as a parser failure ten frames down.
    if (!existsSync(sourcePath)) {
      refuse(
        'MountSourceMissing',
        `mount ${JSON.stringify(mount.component)} declares source ${JSON.stringify(mount.source)}, ` +
          `which does not exist (looked at ${sourcePath}). Sources are resolved against the ` +
          'project root.',
      );
    }

    if (mount.page !== undefined && !pageIds.has(mount.page)) {
      refuse(
        'MountPageUnknown',
        `mount ${JSON.stringify(mount.component)} belongs to page ${JSON.stringify(mount.page)}, ` +
          `which no page declares. Declared pages: ${[...pageIds].join(', ') || '(none)'}.`,
      );
    }

    const resolved: ResolvedMount = {
      component: mount.component,
      source: mount.source,
      sourcePath,
      artifact: mount.artifact ?? artifactKey(mount.source, mount.component),
      page: mount.page,
      expectProvable: mount.expectProvable ?? policies.expectProvable,
      substitute: resolveSubstitution(mount, root, generatedDir),
    };

    // The artifact key is short rather than injective on purpose, so two
    // same-named components in same-named files can land on one directory.
    // That is a build error, not a merge: the second emit would overwrite the
    // first and the page would resume the wrong component.
    const collision = byArtifact.get(resolved.artifact);
    if (collision) {
      refuse(
        'ArtifactKeyCollision',
        `mounts ${JSON.stringify(collision.source)} (${collision.component}) and ` +
          `${JSON.stringify(resolved.source)} (${resolved.component}) both claim the artifact ` +
          `directory ${JSON.stringify(resolved.artifact)}. Give one of them an explicit ` +
          '`artifact` name.',
      );
    }
    byArtifact.set(resolved.artifact, resolved);

    return resolved;
  });
}

/**
 * Where a rewritten module goes, and the glue it calls.
 *
 * The helper's name is derived from the component's, because a project that
 * names its glue after the component it claims should not have to say so
 * twice. The specifier is re-rooted here rather than in the stage: the
 * directory the rewritten module sits in is a configuration fact, and the
 * stage has enough to derive already.
 */
function resolveSubstitution(
  mount: MountDeclaration,
  root: string,
  generatedDir: string,
): ResolvedSubstitution | undefined {
  const declared = mount.substitute;
  if (declared === undefined) return undefined;

  if (!declared.out) {
    refuse(
      'SubstituteOutMissing',
      `mount ${JSON.stringify(mount.component)} declares a substitution with no \`out\`. The ` +
        'rewritten module needs a path; relative ones land under `generatedDir`.',
    );
  }

  if (!declared.claim?.module) {
    refuse(
      'ClaimGlueUndeclared',
      `mount ${JSON.stringify(mount.component)} declares a substitution with no ` +
        '`claim.module`. The rewritten mount point calls glue that publishes the live store and ' +
        'claims the resumed element; which module exports it is yours to say.',
    );
  }

  const outPath = absoluteUnder(generatedDir, declared.out);
  const modulePath = absoluteUnder(root, declared.claim.module);
  const named = existsSync(modulePath);

  return {
    outPath,
    helper: declared.claim.helper ?? `claim${mount.component}`,
    specifier: named ? relativeSpecifier(dirname(outPath), modulePath) : declared.claim.module,
    modulePath: named ? modulePath : undefined,
    banner: declared.banner,
  };
}

/** A path under the root, re-rooted to the directory a generated module sits in. */
function relativeSpecifier(fromDir: string, target: string): string {
  const rerooted = relative(fromDir, target);
  return rerooted.startsWith('.') ? rerooted : `./${rerooted}`;
}

/**
 * A declared path made absolute against a root, for stages that resolve
 * configuration of their own. Exported so there is one answer to "where does
 * this path land" rather than one per stage.
 */
export function resolveUnder(root: string, path: string): string {
  return absoluteUnder(root, path);
}

function absoluteUnder(root: string, path: string): string {
  return isAbsolute(path) ? resolve(path) : resolve(join(root, path));
}

/** The Rolldown entry. */
import unplugin from './index.ts';

export default unplugin.rolldown;

/** The Rollup entry. Analyze and emit run here unchanged; the page transforms are Vite-only until a slice gives them a trigger of their own. */
import unplugin from './index.ts';

export default unplugin.rollup;

/** The Rspack entry. */
import unplugin from './index.ts';

export default unplugin.rspack;

/**
 * The browser half's public surface.
 *
 * Everything reachable from here is zero-dependency and framework-free by
 * standing policy: it reads emitted artifacts, boots a component on first
 * touch, and defers the group until something asks for it. Nothing hydrates —
 * there is no second render of a tree the server already produced, so the
 * vocabulary is group activation, deferred render, first-touch boot.
 *
 * What is deliberately absent is the artifact registry bound to a *particular*
 * project's artifact directory. That binding is a glob over the consumer's own
 * output, so the consumer makes it; this package ships the machinery it feeds.
 */

export { createRegistry, isActionSlot } from '../../../src/resume/registry.ts';
export type {
  ActionCaptureSlotSpec,
  ActionSpec,
  BindingSpec,
  Bundle,
  CaptureSlotSpec,
  CellCaptureSlotSpec,
  CellSpec,
  HandlerModule,
  Registry,
  Slots,
  StoreSpec,
  TemplateArtifact,
  WiringSpec,
} from '../../../src/resume/registry.ts';

export { createStoreRegistry } from '../../../src/resume/stores.ts';
export type { SlotPath, StoreRegistry } from '../../../src/resume/stores.ts';

export { createResumer, resumeBundle } from '../../../src/resume/resumer.ts';
export type { Cell, ResumeOptions, ResumeStats, ResumedApp } from '../../../src/resume/resumer.ts';

export { cellKernel, createSignal, flush, untrack } from '../../../src/resume/cells.ts';
export type { Accessor, CellBackend, Setter } from '../../../src/resume/cells.ts';

export { locate } from '../../../src/resume/locate.ts';

export {
  DEFAULT_DEFER_EVENTS,
  DEFAULT_DEFER_SIGNALS,
  deferGroup,
  pathTo,
} from '../../../src/resume/defer.ts';
export type {
  DeferOptions,
  DeferStats,
  DeferredGroup,
  QueuedEvent,
} from '../../../src/resume/defer.ts';

/**
 * Analyze and emit: the pass over every declared mount, and the artifacts it
 * writes.
 *
 * The body is a plain function of explicit inputs. Nothing here asks a bundler
 * for anything — it reads sources and writes an artifact tree — which is why
 * the same code serves a universal `buildStart` hook, a consumer's own script,
 * and a test that runs it into a scratch directory.
 *
 * A mount declared provable that comes back fallback is a hard failure, not a
 * warning. These are the positive controls of the whole configuration: if the
 * pass stops proving them, the build is no longer the thing it claims to be
 * and should say so rather than emit a page with a hole in it.
 */

import { existsSync, readdirSync, rmSync } from 'node:fs';
import { join, relative } from 'pathe';

import { runComptime } from '../../../src/comptime/index.ts';
import type { Analysis } from '../../../src/comptime/types.ts';
import type { ResolvedMount, ResolvedOptions } from '../types.ts';

/** What one mount's pass produced. `emittedDir` is absolute; null when the verdict was fallback. */
export interface MountOutcome {
  mount: ResolvedMount;
  analysis: Analysis;
  emittedDir: string | null;
}

/** What the stage did, for a caller that wants to assert on it rather than read logs. */
export interface AnalyzeReport {
  outcomes: MountOutcome[];
  /** Artifact directories removed because no declared mount claimed them. Absolute. */
  pruned: string[];
}

/** A mount that had to be provable and was not. */
export class UnprovableMountError extends Error {
  readonly outcomes: MountOutcome[];

  constructor(message: string, outcomes: MountOutcome[]) {
    super(message);
    this.name = 'UnprovableMountError';
    this.outcomes = outcomes;
  }
}

export interface AnalyzeStageOptions {
  /** Where the per-mount verdict lines go. Defaults to stdout. */
  log?: (line: string) => void;
}

/**
 * Runs the pass over every declared mount, pruning first and refusing last.
 *
 * Pruning comes first because emission overwrites per mount: a mount *removed*
 * from the declaration would otherwise leave its directory behind, and a page
 * that globs the artifact tree would keep serving it. The declaration is the
 * truth; anything else under the artifact directory is stale.
 */
export function runAnalyzeStage(
  options: ResolvedOptions,
  stage: AnalyzeStageOptions = {},
): AnalyzeReport {
  const log = stage.log ?? ((line: string) => console.log(line));

  const pruned = options.policies.pruneStaleArtifacts ? pruneStaleArtifacts(options) : [];

  const outcomes: MountOutcome[] = [];
  for (const mount of options.mounts) {
    const { analysis, emitted } = runComptime(mount.sourcePath, {
      root: options.corpusRoot,
      outRoot: options.artifactDir,
      component: mount.component,
    });
    outcomes.push({ mount, analysis, emittedDir: emitted?.dir ?? null });

    if (analysis.status !== 'provable') continue;

    log(
      `provable  ${analysis.module} (${analysis.component}): ` +
        `${analysis.cells.length} cell(s), ${analysis.bindings.length} binding(s), ` +
        `${analysis.handlers.length} handler(s) -> ` +
        `${relative(options.corpusRoot, emitted!.dir)}/`,
    );
  }

  const unprovable = outcomes.filter(
    (outcome) => outcome.mount.expectProvable && outcome.analysis.status !== 'provable',
  );
  if (unprovable.length > 0) throw unprovableError(unprovable, outcomes.length);

  return { outcomes, pruned };
}

/**
 * The refusal message carries every reason with its line and column, because a
 * verdict without a location is a verdict no one can act on — the point of the
 * message is that the reader opens the file at the right line.
 */
function unprovableError(unprovable: MountOutcome[], total: number): UnprovableMountError {
  const lines: string[] = [];
  for (const { mount, analysis } of unprovable) {
    lines.push(`fallback  ${mount.source} (${mount.component}) — expected provable`);
    for (const reason of analysis.reasons) {
      lines.push(`          ${reason.code} @ ${reason.loc.line}:${reason.loc.column} — ${reason.message}`);
    }
  }
  lines.push('');
  lines.push(`${unprovable.length} of ${total} declared components are no longer provable.`);
  return new UnprovableMountError(lines.join('\n'), unprovable);
}

function pruneStaleArtifacts(options: ResolvedOptions): string[] {
  if (!existsSync(options.artifactDir)) return [];

  const keep = new Set(options.mounts.map((mount) => join(options.artifactDir, mount.artifact)));
  const pruned: string[] = [];

  for (const entry of readdirSync(options.artifactDir, { withFileTypes: true })) {
    if (!entry.isDirectory()) continue;
    const dir = join(options.artifactDir, entry.name);
    if (keep.has(dir)) continue;
    rmSync(dir, { recursive: true, force: true });
    pruned.push(dir);
  }

  return pruned;
}

/**
 * One capture: the page's first paint, taken by running its built group in a
 * headless document.
 *
 * ── Why a capture and not server rendering ────────────────────────────────
 * A server renderer emits markup for a *tree*, and it emits it with the
 * markers its own client half claims against. What this pipeline serves is
 * markup a proven component's locators address directly, with nothing claiming
 * anything — so the two are not the same bytes, and the framework would have to
 * be taught about ours for them to be. Running the code instead asks no such
 * favour: the shell is an output of the same module, at the same state, as the
 * render that will replace it on the first interaction, which is what makes the
 * replacement invisible.
 *
 * ── Why the snapshot is synchronous ───────────────────────────────────────
 * The markup is read before anything is awaited, so no microtask has run and no
 * asynchronous source behind the page's own loading boundary can have resolved.
 * What that captures is the paint a browser shows first, rather than a later
 * state that would flash back to the first one when the group renders.
 *
 * ── Why this is a module of its own ───────────────────────────────────────
 * It is the body of a child process. The caller runs it once per capture in a
 * process of its own, so each capture gets a fresh module registry, a fresh
 * document and a fresh store — and two captures that agree agree because the
 * code is deterministic, not because the second one inherited the first one's
 * memory. Everything else stays out of this file: a DOM, node's own URL helper
 * and a path normalizer, and nothing that would make a child process pay for
 * the rest of the package.
 */

import { fileURLToPath, pathToFileURL } from 'node:url';
import { resolve } from 'pathe';

// The headless DOM ships no types of its own, and a types package would be a
// dependency taken on for the sake of one constructor. What this file calls is
// declared below instead, so the surface it depends on is written down rather
// than inferred as `any`. Should the implementation ever ship types, this
// suppression is what stops compiling and says so.
// @ts-expect-error -- untyped module; `HeadlessDom` below is the contract
import { JSDOM as UntypedDom } from 'jsdom';

/** The window this file touches, and nothing else it happens to have. */
interface CaptureWindow {
  document: Document;
  DOMTokenList: { prototype: { supports: (token: string) => boolean } };
  close(): void;
}

/** One headless document, as its constructor returns it. */
interface HeadlessDom {
  window: CaptureWindow;
}

const JSDOM = UntypedDom as unknown as new (
  html: string,
  options: { url: string },
) => HeadlessDom;

/**
 * The file a capture is run as, whatever shape the package ships in.
 *
 * Derived from this module's own URL rather than from a path someone wrote
 * down, because after bundling there is no such path: this module ends up
 * inside one of the package's entry bundles, and `import.meta.url` names
 * whichever one that is. Running that file as a script takes the branch at the
 * bottom of this module, which is why the child needs no import of its own and
 * no export name that a bundler is free to rename.
 */
export const CAPTURE_MODULE_PATH = resolve(fileURLToPath(import.meta.url));

/** What tells the module at the bottom of this file that it is the child. */
export const CAPTURE_FLAG = '--unplugin-solid-resumability-capture';

/**
 * What separates the captured markup from anything the page's own code wrote
 * to standard output. The parent reads what follows the last one.
 */
export const CAPTURE_PAYLOAD_MARK = '\n<<<unplugin-solid-resumability:capture>>>';

/** Everything one capture needs, and nothing it could derive wrongly. */
export interface CaptureRequest {
  /** Absolute path of the built group chunk to run. */
  chunkPath: string;
  /** The document the group renders into, as markup. The target element is empty in it. */
  documentHtml: string;
  /** How the target element is addressed inside that document. */
  rootSelector: string;
  /** The export the chunk renders through. It takes the element and returns a disposer. */
  execute: string;
  /**
   * The origin the document claims.
   *
   * A build cannot know where the page will be served from, and nothing in a
   * first paint should depend on it; a document with no origin at all, though,
   * makes a relative URL throw. So: a local one, stated once.
   */
  origin?: string;
}

const DEFAULT_ORIGIN = 'http://localhost/';

/**
 * Everything the built chunk expects a browser to have.
 *
 * Copied wholesale from the window rather than listed, because the list is the
 * framework's business: a missing entry would be a capture that failed for a
 * reason having nothing to do with the page, and the failure would read as a
 * fault in the markup.
 */
function installGlobals(window: CaptureWindow): void {
  // A bundler's module-preload polyfill asks whether the `modulepreload` link
  // relation is supported, and this DOM throws for an attribute with no defined
  // tokens — which would abort the chunk's evaluation before it exported
  // anything. What the answer is does not affect what is captured.
  window.DOMTokenList.prototype.supports = () => true;

  const host = globalThis as Record<string, unknown>;
  host.window = window;
  host.document = window.document;

  for (const key of Object.getOwnPropertyNames(window)) {
    if (key in globalThis) continue;
    let value: unknown;
    try {
      value = (window as unknown as Record<string, unknown>)[key];
    } catch {
      continue;
    }
    if (value === null || (typeof value !== 'object' && typeof value !== 'function')) continue;
    try {
      Object.defineProperty(globalThis, key, { value, configurable: true, writable: true });
    } catch {
      // A global the host owns and will not give up is a global the chunk can
      // have the host's copy of.
    }
  }
}

/**
 * Runs the group once and returns what the target element contains.
 *
 * Exported rather than kept private because the child process is a detail of
 * how isolation is bought, not of what a capture is: a caller that wants one
 * capture in the process it already has can call this directly, and will get
 * the same bytes for as long as its own registry is clean.
 */
export async function captureShell(request: CaptureRequest): Promise<string> {
  const dom = new JSDOM(request.documentHtml, { url: request.origin ?? DEFAULT_ORIGIN });
  installGlobals(dom.window);

  const group = (await import(pathToFileURL(request.chunkPath).href)) as Record<string, unknown>;
  const execute = group[request.execute];
  if (typeof execute !== 'function') {
    throw new Error(
      `capture: the built chunk ${request.chunkPath} exports no \`${request.execute}\` function, ` +
        'so there is nothing to render. `prerender.execute` names the export the group renders ' +
        'through; the generated group module exports `execute`.',
    );
  }

  const root = dom.window.document.querySelector(request.rootSelector);
  if (root === null) {
    throw new Error(
      `capture: the capture document has no element matching ${JSON.stringify(request.rootSelector)}, ` +
        'so the group has nowhere to render.',
    );
  }

  // Synchronous, and read before anything is awaited: an asynchronous source
  // behind the page's loading boundary has not had a microtask to resolve in.
  const dispose = (execute as (element: Element) => () => void)(root);
  const html = root.innerHTML;

  dispose();
  dom.window.close();
  return html;
}

/** A captured paint, parsed, and the handle that lets it go. */
export interface ParsedMarkup {
  /** The element the markup was parsed into. Its children are the markup. */
  container: Element;
  close(): void;
}

/**
 * Parses markup this build already captured.
 *
 * Here rather than in the stage that uses it because the headless DOM's one
 * typed contract lives in this file, and a second one somewhere else would be
 * two places to update when the implementation changes. What the caller gets is
 * a container whose children are the markup — the same relationship a mount
 * container has to the component it holds, which is what makes a locator mean
 * the same thing against it.
 */
export function parseCapturedMarkup(html: string, origin = DEFAULT_ORIGIN): ParsedMarkup {
  const dom = new JSDOM(`<!doctype html><html><body>${html}</body></html>`, { url: origin });
  return {
    container: dom.window.document.body,
    close: () => dom.window.close(),
  };
}

// The child half, and the only thing that takes this branch is a process this
// package started for one capture. Importing this module never does: the guard
// asks whether this file is the script node was given, not merely whether the
// flag is on the command line.
//
// Nothing is awaited at the top level here. A module that awaits is an
// asynchronous module for everyone who imports it, and what this branch is for
// is a process that imports nothing.
if (
  process.argv[2] === CAPTURE_FLAG &&
  resolve(process.argv[1] ?? '') === CAPTURE_MODULE_PATH
) {
  void captureShell(JSON.parse(process.argv[3] ?? '{}') as CaptureRequest).then((html) => {
    process.stdout.write(CAPTURE_PAYLOAD_MARK + JSON.stringify({ html }));
  });
}

/**
 * The two chunking constraints the resumed page depends on.
 *
 * Neither is a preference. `manifest` is how the later stages find the chunk a
 * generated module compiled to — without it there is nothing to look the
 * deferred group up in. `experimentalMinChunkSize: 0` keeps authored chunk
 * boundaries: the bundler's small-chunk merging would otherwise fuse handler
 * chunks into each other, and a merged handler chunk is a handler that loads
 * because a *different* button was pressed. Neither constraint can move a byte
 * from lazy to eager; they only stop lazy bytes from being pooled.
 *
 * Applied by mutating the config in place rather than by returning a partial,
 * and only ever field by field. A consumer who already named their manifest
 * keeps their name; a consumer with several outputs gets the constraint on
 * each of them and loses none of their own settings.
 */

import type { UnpluginOptions } from 'unplugin';

import type { ResolvedOptions } from '../types.ts';

/** The narrow shape this stage touches. Structural on purpose: it costs no dependency on a bundler's types. */
export interface ChunkingConfig {
  build?: {
    manifest?: boolean | string;
    rollupOptions?: {
      output?: ChunkingOutput | ChunkingOutput[];
      [key: string]: unknown;
    };
    [key: string]: unknown;
  };
  [key: string]: unknown;
}

/** Open on purpose: every other field of an output is the consumer's and is passed through untouched. */
export interface ChunkingOutput {
  experimentalMinChunkSize?: number;
  [key: string]: unknown;
}

/**
 * Merges the constraints into `config`, returning it for callers who prefer a
 * value. Safe to run twice on one config.
 */
export function applyChunkingConstraints<T extends ChunkingConfig>(config: T): T {
  const build = (config.build ??= {});

  // Truthy already means a manifest is being written, possibly under a name
  // the consumer chose. Only the absence is ours to fill.
  if (!build.manifest) build.manifest = true;

  const rollupOptions = (build.rollupOptions ??= {});
  if (rollupOptions.output === undefined) rollupOptions.output = {};
  const declared = rollupOptions.output;
  const outputs: ChunkingOutput[] = Array.isArray(declared) ? declared : [declared];

  // Unconditional: a nonzero floor is exactly the merging this constraint
  // exists to prevent, so honouring a consumer's value here would honour it
  // into a broken build.
  for (const output of outputs) output.experimentalMinChunkSize = 0;

  return config;
}

/** The stage as a plugin fragment: a Vite `config` hook and nothing else. */
export function chunkingPlugin(options: ResolvedOptions): UnpluginOptions {
  return {
    name: 'unplugin-solid-resumability:chunking',
    enforce: 'pre',
    vite: {
      // Typed `unknown` and narrowed here rather than taken as the bundler's
      // own config type: this package declares no bundler dependency, and the
      // two fields it touches are the two it declares.
      config(config: unknown) {
        if (!options.policies.chunking) return;
        applyChunkingConstraints(config as ChunkingConfig);
      },
    },
  };
}

/**
 * Fallback omission: the branch a fully provable page cannot take, removed.
 *
 * A resumable page carries two paths. Components the pass proved are resumed
 * from artifacts against markup already in the document; components it refused
 * are rendered the ordinary way, which means the ordinary renderer has to be
 * reachable. Reachable is the operative word — the branch is written as a
 * dynamic `import()` precisely so the renderer is a chunk the page fetches only
 * if it needs one.
 *
 * On a page where every declared mount came back provable, it never needs one.
 * The branch is unreachable code, and the chunk behind it is a file the build
 * emits for a fetch that cannot happen. `policies.fallback: 'auto-omit'` is the
 * answer, and the derivation under it is one line:
 *
 *   A page may omit its fallback branch IFF every mount declared against it is
 *   provable.
 *
 * Sound in both directions. If every mount is provable, every mount on the page
 * resumes and the branch's guard is never entered — so removing it removes
 * nothing the page could reach. If any mount is not provable, the page
 * needs the renderer for that mount and the branch stays. The verdicts are the
 * pass's own, taken from the same analysis the artifacts came out of, so this
 * is not a heuristic about what a page *probably* needs.
 *
 * ── What omission actually is ─────────────────────────────────────────────
 * The `import()` call is rewritten out of the declaring module, in `transform`,
 * before the bundler resolves it. Nothing imports the fallback module any more,
 * so no chunk is emitted for it: not a smaller chunk, not a stub that throws,
 * NO CHUNK. That distinction is the whole measurement — a stub would still be a
 * dynamic entry, still be in the manifest, still be a file the page names.
 *
 * What replaces it is a rejected promise carrying the reason. The branch is
 * unreachable *by the derivation*, not by construction: a document that grew a
 * mount nobody declared would reach it, and the honest answer to that is a page
 * that fails loudly rather than one that silently renders nothing. The refusal
 * names the page, so the message is a repair instruction.
 *
 * ── Why the consumer names the module ─────────────────────────────────────
 * Everything about WHETHER to omit is derived. Everything about WHERE the
 * branch is written is declared: `page.fallback = { module, specifier }`. A
 * stage that went hunting for `import()` calls that looked like a renderer
 * would be guessing at the one thing it must not guess at, and the failure mode
 * of a wrong guess is a page that lost an import it needed. So the specifier is
 * matched exactly, once, and anything else is a refusal by name.
 */

import { relative } from 'pathe';
import type { UnpluginOptions } from 'unplugin';

import type { ResolvedOptions, ResolvedPage, ResolvedPageFallback } from '../types.ts';
import type { MountOutcome } from './analyze.ts';

/** Every way this stage declines to omit a branch. */
export type FallbackRefusalName = 'FallbackImportMissing' | 'FallbackImportAmbiguous';

/**
 * A fallback branch this stage will not rewrite.
 *
 * `name` is the refusal's own rather than the class's, so a caller can branch
 * on which rule fired without matching on prose that may be reworded.
 */
export class FallbackOmissionError extends Error {
  readonly page: string;

  constructor(name: FallbackRefusalName, message: string, page: string) {
    super(message);
    this.name = name;
    this.page = page;
  }
}

/** One page whose fallback branch the build is dropping, and where it is written. */
export interface OmittedFallback {
  page: ResolvedPage;
  fallback: ResolvedPageFallback;
  /** Every mount declared against the page, all of them provable. */
  mounts: string[];
}

/**
 * The derivation, run over the pass's own verdicts.
 *
 * A page qualifies when the policy asks for omission, the page says where its
 * branch is, at least one mount is declared against it, and every one of those
 * mounts came back provable. The "at least one" clause is not pedantry: a page
 * with no declared mounts is trivially all-provable, and dropping the renderer
 * from a page the pass never looked at would be an omission derived from
 * nothing.
 */
export function omittedFallbacks(
  options: ResolvedOptions,
  outcomes: MountOutcome[],
): OmittedFallback[] {
  if (options.policies.fallback !== 'auto-omit') return [];

  const omitted: OmittedFallback[] = [];

  for (const page of options.pages) {
    if (page.fallback === false) continue;

    const mine = outcomes.filter((outcome) => outcome.mount.page === page.id);
    if (mine.length === 0) continue;
    if (mine.some((outcome) => outcome.analysis.status !== 'provable')) continue;

    omitted.push({
      page,
      fallback: page.fallback,
      mounts: mine.map((outcome) => outcome.mount.component),
    });
  }

  return omitted;
}

/**
 * A dynamic import of one exact specifier, in either quoting the author may
 * have used.
 *
 * Written against the call rather than against the module: `import("./x.ts")`
 * is the whole form, and a static `import … from "./x.ts"` in the same file
 * would be a different claim about the same module — one this stage has no
 * business rewriting, because a static import is not a branch.
 */
function importCallOf(specifier: string): RegExp {
  const quoted = specifier.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  return new RegExp(`\\bimport\\(\\s*(['"\`])${quoted}\\1\\s*\\)`, 'g');
}

/**
 * The rewrite, as a function of the source, so a test can run it without a
 * bundler and the build and the tests cannot diverge.
 *
 * Exactly one occurrence, or a refusal. Zero means the specifier the page
 * declared is not the specifier the module writes — a config that would
 * otherwise report an omission it did not make. More than one means two
 * branches share a specifier, and which of them is THE fallback branch is not
 * decidable from here.
 */
export function omitFallbackImport(code: string, omission: OmittedFallback): string {
  const { specifier } = omission.fallback;
  const found = [...code.matchAll(importCallOf(specifier))];

  if (found.length === 0) {
    throw new FallbackOmissionError(
      'FallbackImportMissing',
      `page ${JSON.stringify(omission.page.id)} declares its fallback branch as ` +
        `\`import(${JSON.stringify(specifier)})\` in ${omission.fallback.module}, and that ` +
        'module contains no such call. Omission rewrites the call it was told about and nothing ' +
        'else, so a specifier that matches nothing is a configuration error rather than a ' +
        'no-op — the build would report an omission it did not make.',
      omission.page.id,
    );
  }

  if (found.length > 1) {
    throw new FallbackOmissionError(
      'FallbackImportAmbiguous',
      `${omission.fallback.module} imports ${JSON.stringify(specifier)} dynamically ` +
        `${found.length} times, so which call is page ${JSON.stringify(omission.page.id)}'s ` +
        'fallback branch is not decidable. One branch per page: reach the renderer through a ' +
        'single import, or give the branch its own module.',
      omission.page.id,
    );
  }

  const match = found[0]!;
  const start = match.index!;
  return (
    code.slice(0, start) +
    refusalExpression(omission) +
    code.slice(start + match[0].length)
  );
}

/**
 * What the branch becomes: a promise that rejects with the reason it is gone.
 *
 * Deliberately an expression of the same shape the call had, so `await` on it
 * still reads as `await`, and deliberately short — this lands in the page's
 * EAGER chunk, and a paragraph of prose there would be bytes charged to every
 * visitor to explain a branch none of them will take.
 */
function refusalExpression(omission: OmittedFallback): string {
  const reason =
    `page "${omission.page.id}" is fully provable, so its fallback branch was omitted at build time`;
  return `Promise.reject(new Error(${JSON.stringify(reason)}))`;
}

export interface FallbackReport {
  omitted: OmittedFallback[];
}

/**
 * The stage's own plugin: one `transform`, universal across bundlers.
 *
 * `transform` is one of the six hooks unplugin abstracts, so this needs no
 * per-bundler key — the branch is removed the same way under vite, rollup,
 * webpack and the rest. `enforce: 'pre'` so the module arrives as its author
 * wrote it; a specifier already rewritten by somebody else's resolver is not
 * the specifier the page declared.
 */
export function fallbackPlugin(input: {
  options: () => ResolvedOptions;
  outcomes: () => MountOutcome[];
}): UnpluginOptions {
  return {
    name: 'unplugin-solid-resumability:fallback',
    enforce: 'pre',

    transform(code: string, id: string) {
      // An id comparison per module, and nothing else until one matches: the
      // omissions are re-derived here rather than captured because the pass
      // that produces the verdicts runs in a `buildStart` this hook cannot
      // order itself against, and a stale capture would omit on last build's
      // answer.
      const mine = omittedFallbacks(input.options(), input.outcomes()).find(
        (omission) => normalize(id) === normalize(omission.fallback.modulePath),
      );
      if (mine === undefined) return undefined;

      return { code: omitFallbackImport(code, mine), map: null };
    },
  };
}

/** Bundler ids arrive with query strings and platform separators; module identity has neither. */
function normalize(id: string): string {
  return id.split('?')[0]!.replace(/\\/g, '/');
}

/**
 * The stage body, for a consumer whose bundler has no hook to hang it on and
 * for the build log: which pages dropped their branch, and on whose verdicts.
 */
export function runFallbackStage(
  options: ResolvedOptions,
  outcomes: MountOutcome[],
  stage: { log?: (line: string) => void } = {},
): FallbackReport {
  const log = stage.log ?? ((line: string) => console.log(line));
  const omitted = omittedFallbacks(options, outcomes);

  for (const omission of omitted) {
    log(
      `omitted      ${omission.page.id} fallback (${omission.mounts.length} provable mount(s)) -> ` +
        `${relative(options.root, omission.fallback.modulePath)} imports ` +
        `${JSON.stringify(omission.fallback.specifier)} no more`,
    );
  }

  return { omitted };
}

/**
 * The deferral group of a page, as a module: one chunk, one import, one
 * execution.
 *
 * A page's provable components resume from markup that is already in the
 * document. Everything else on that page — the framework, the store, the
 * components that share it — is one connected component of the shared-source
 * graph, and one connected component is one module. Every static import in the
 * module this stage emits is a byte that is not on the wire until the first
 * interaction asks for it, and there is exactly one import site for it, so the
 * bytes arrive once.
 *
 * ── What the emitted module does ──────────────────────────────────────────
 * Render-and-replace. The served page is a captured first paint that no
 * framework claims; nothing is asked to take it over. The shell is discarded
 * and the same code that produced it runs again at the same state, so the
 * first paint after the swap is the paint that was already there.
 *
 * Two things do not survive a swap on their own, and the emitted module
 * carries both across it:
 *
 *   the resumed mounts   The live elements — served markup, delegated
 *                        listeners, whatever the user has typed into them —
 *                        are detached before the root is cleared and handed to
 *                        the substituted mount points, so the render inserts
 *                        THOSE nodes rather than copies of them.
 *   focus and selection  Properties of the document, not of any node. Recorded
 *                        before the swap and restored after, and emitted only
 *                        when the page asked for them (`carryFocus`).
 *
 * What it does not do is wait. An asynchronous projection is not awaited:
 * awaiting it would render the loaded state at the swap and the swap would
 * become visible.
 *
 * ── Everything here is derived ────────────────────────────────────────────
 * The entry component's module is the substituted module of a mount on this
 * page. The glue is the module that page's substitution already names. The
 * mounts are found by the attribute the inlining stage stamps into them, over
 * the artifact keys the pass emitted. The template glob addresses those same
 * artifact directories from wherever the consumer put this module. Nothing in
 * the emitted text is a name this package knows in advance.
 */

import { existsSync, mkdirSync, statSync, writeFileSync } from 'node:fs';
import { dirname, join, relative } from 'pathe';
import { Analyzer } from 'yuku-analyzer';

import { findComponents } from '../../../src/comptime/discover.ts';
import { RESUME_ATTRIBUTE } from '../html.ts';
import { resolveUnder } from '../options.ts';
import type {
  GroupPolicy,
  ResolvedMount,
  ResolvedOptions,
  ResolvedPage,
  SubstitutionResult,
} from '../types.ts';

/** Every shape this stage declines to generate a module for. */
export type GroupRefusalName =
  | 'GroupNotDeclared'
  | 'GroupEntryModuleMissing'
  | 'GroupEntryComponentMissing'
  | 'GroupEntryComponentNotExported'
  | 'GroupEntryComponentAmbiguous'
  | 'GroupGlueUndeclared';

/**
 * A group this stage will not generate.
 *
 * `name` is the refusal's own name rather than the class's, so a caller can
 * branch on which rule fired without matching on prose that may be reworded.
 */
export class GroupGenerationError extends Error {
  readonly page: ResolvedPage;

  constructor(name: GroupRefusalName, message: string, page: ResolvedPage) {
    super(message);
    this.name = name;
    this.page = page;
  }
}

/** One generated group module: what it is, where it goes, and what it reaches. */
export interface GeneratedGroup {
  page: ResolvedPage;
  policy: GroupPolicy;
  /** Absolute path the module is written to. */
  path: string;
  code: string;
  /** Every specifier the module imports, in emitted order. Globs included, as written. */
  imports: string[];
  /** The mounts whose live elements the module claims, in declaration order. */
  claims: ResolvedMount[];
}

export interface GroupStageOptions {
  /** Where the per-page lines go. Defaults to stdout. */
  log?: (line: string) => void;
}

export interface GroupReport {
  groups: GeneratedGroup[];
}

/** The framework call the emitted module renders through, when a page names no other. */
const DEFAULT_RENDER = { module: '@solidjs/web', named: 'render' };

/** The glue names the emitted module calls, when a page names no others. */
const DEFAULT_GLUE = { createMount: 'createMount', offerClaim: 'offerClaim' };

/**
 * Generates and writes the group module of every page that declares one.
 *
 * Runs in the same pass as analyze and substitution, and after them: it reads
 * their results, and the frozen module graph these builds are measured against
 * names generated modules by path, so they have to be real files before module
 * resolution begins.
 */
export function runGroupStage(
  options: ResolvedOptions,
  substitutions: SubstitutionResult[],
  stage: GroupStageOptions = {},
): GroupReport {
  const log = stage.log ?? ((line: string) => console.log(line));
  const groups: GeneratedGroup[] = [];

  for (const page of options.pages) {
    if (page.group === false) continue;

    const group = generateGroupModule(options, page, substitutions);
    mkdirSync(dirname(group.path), { recursive: true });
    writeFileSync(group.path, group.code, 'utf8');
    groups.push(group);

    log(
      `group        ${page.id} (${group.claims.length} resumed mount(s)) -> ` +
        `${relative(options.root, group.path)}`,
    );
  }

  return { groups };
}

/**
 * The generation as a function of the configuration and the substitutions, so
 * a test can run it without writing a file and the build and the tests cannot
 * diverge.
 */
export function generateGroupModule(
  options: ResolvedOptions,
  page: ResolvedPage,
  substitutions: SubstitutionResult[],
): GeneratedGroup {
  const policy = page.group;
  if (policy === false) {
    throw new GroupGenerationError(
      'GroupNotDeclared',
      `page ${JSON.stringify(page.id)} declares no group, so there is no module to generate. A ` +
        'page whose components all resume needs none.',
      page,
    );
  }

  const modulePath = resolveUnder(options.root, policy.moduleId);
  const fromDir = dirname(modulePath);

  const onPage = substitutions.filter((result) => result.mount.page === page.id);
  if (onPage.length === 0) {
    throw new GroupGenerationError(
      'GroupEntryModuleMissing',
      `page ${JSON.stringify(page.id)} declares a group rendering ` +
        `\`${policy.entryComponent}\`, but no mount on this page declares a substitution. The ` +
        'group renders the rewritten module, so a page with nothing rewritten has nothing for ' +
        'its group to render.',
      page,
    );
  }

  const entry = entryModule(page, policy, onPage);
  const claims = onPage.map((result) => result.mount);
  const glue = glueSpecifier(page, policy, onPage, options, fromDir);

  const render = { ...DEFAULT_RENDER, ...policy.render };
  const glueNames = { ...DEFAULT_GLUE, ...policy.glue };
  const carryFocus = policy.carryFocus ?? true;

  const templateGlobs = claims.map((mount) =>
    specifier(fromDir, join(options.artifactDir, mount.artifact, 'template.js')),
  );
  const entrySpecifier = specifier(fromDir, entry.path);

  const imports = [render.module, entrySpecifier, glue, ...templateGlobs];

  const code = emit({
    page,
    policy,
    render,
    glueNames,
    glueSpecifier: glue,
    entrySpecifier,
    templateGlobs,
    claims,
    carryFocus,
    rootSelector: rootSelectorOf(page, policy),
  });

  return { page, policy, path: modulePath, code, imports, claims };
}

/**
 * The rewritten module the group renders, and the proof that it renders
 * something.
 *
 * Checked against the emitted source rather than assumed: a group whose entry
 * component is not in the module it would import is a page that builds, ships
 * a chunk, and throws at the first interaction.
 */
function entryModule(
  page: ResolvedPage,
  policy: GroupPolicy,
  onPage: SubstitutionResult[],
): SubstitutionResult {
  const carriers = onPage.filter((result) => {
    const site = componentSite(result, policy.entryComponent);
    return site !== null && site.exported;
  });

  if (carriers.length > 1) {
    throw new GroupGenerationError(
      'GroupEntryComponentAmbiguous',
      `${carriers.length} rewritten modules on page ${JSON.stringify(page.id)} export ` +
        `\`${policy.entryComponent}\`. Which one the group renders is not decidable; rename one, ` +
        'or declare the group on the page that owns it.',
      page,
    );
  }

  const carrier = carriers[0];
  if (carrier !== undefined) return carrier;

  // Declared but not exported is its own answer, and a different one: the
  // component is there and the module simply cannot be asked for it.
  const unexported = onPage.find((result) => componentSite(result, policy.entryComponent) !== null);
  if (unexported !== undefined) {
    throw new GroupGenerationError(
      'GroupEntryComponentNotExported',
      `\`${policy.entryComponent}\` is declared in the module rewritten from ` +
        `${unexported.mount.source} but is not exported from it, so the group cannot import it. ` +
        'Export it from the source module.',
      page,
    );
  }

  throw new GroupGenerationError(
    'GroupEntryComponentMissing',
    `no rewritten module on page ${JSON.stringify(page.id)} declares a component named ` +
      `\`${policy.entryComponent}\`. The rewritten modules on this page are ` +
      `${onPage.map((result) => JSON.stringify(result.mount.source)).join(', ')}. ` +
      '`entryComponent` is the component the group renders, and it has to be one of theirs.',
    page,
  );
}

/**
 * One component of the rewritten module, read off its own source.
 *
 * A single-module analyzer is enough: whether a module declares a component
 * and exports it is a question about that module, and linking it to the rest
 * of the corpus would answer nothing this asks.
 */
function componentSite(result: SubstitutionResult, component: string) {
  const analyzer = new Analyzer();
  const moduleInfo = analyzer.addFile(result.path, result.code);
  analyzer.link();
  return findComponents(moduleInfo).find((site) => site.name === component) ?? null;
}

/**
 * The module the emitted code calls for its mount glue.
 *
 * Defaulted from the substitution's own claim module, because the glue that
 * hands a resumed element to a substituted mount point and the glue that
 * offers it are two halves of one protocol and live together in every project
 * that has written it once.
 */
function glueSpecifier(
  page: ResolvedPage,
  policy: GroupPolicy,
  onPage: SubstitutionResult[],
  options: ResolvedOptions,
  fromDir: string,
): string {
  const declared = policy.glue?.module;
  if (declared !== undefined) {
    const target = resolveUnder(options.root, declared);
    return existsAsFile(target) ? specifier(fromDir, target) : declared;
  }

  const inherited = onPage.find((result) => result.mount.substitute?.modulePath !== undefined);
  if (inherited !== undefined) {
    return specifier(fromDir, inherited.mount.substitute!.modulePath!);
  }

  // A bare specifier the substitution passed through has no path to re-root
  // from, so it is emitted as the consumer wrote it.
  const bare = onPage.find((result) => result.mount.substitute !== undefined);
  if (bare !== undefined) return bare.mount.substitute!.specifier;

  throw new GroupGenerationError(
    'GroupGlueUndeclared',
    `page ${JSON.stringify(page.id)} declares a group, but no module on it names the glue the ` +
      'group calls to build a mount from a template and to offer a live one to its substituted ' +
      'mount point. Declare `group.glue.module`.',
    page,
  );
}

/**
 * A declared glue module that resolves to a file is re-rooted to the emitted
 * module's directory; anything else is a bare specifier, somebody else's
 * resolution, and is emitted exactly as written.
 */
function existsAsFile(path: string): boolean {
  return existsSync(path) && statSync(path).isFile();
}

/**
 * How the emitted `execute` finds the element it renders into when its caller
 * names none: the page's own root selector, which the capture policy already
 * states when there is one.
 */
function rootSelectorOf(page: ResolvedPage, policy: GroupPolicy): string | undefined {
  if (policy.rootSelector !== undefined) return policy.rootSelector;
  if (page.prerender !== false) return page.prerender.rootSelector;
  return undefined;
}

/**
 * A string literal for the emitted module, in the delimiter that leaves it
 * readable: double quotes, unless the text carries them and no single quote of
 * its own — a selector escaped into `\"` is a selector nobody wants to read.
 */
function quote(text: string): string {
  if (text.includes('"') && !text.includes("'")) return `'${text}'`;
  return JSON.stringify(text);
}

/** A relative specifier from the emitted module's directory, posix-shaped and explicitly relative. */
function specifier(fromDir: string, target: string): string {
  const path = relative(fromDir, target);
  return path.startsWith('.') ? path : `./${path}`;
}

interface EmitInput {
  page: ResolvedPage;
  policy: GroupPolicy;
  render: { module: string; named: string };
  glueNames: { createMount: string; offerClaim: string };
  glueSpecifier: string;
  entrySpecifier: string;
  templateGlobs: string[];
  claims: ResolvedMount[];
  carryFocus: boolean;
  rootSelector: string | undefined;
}

/**
 * The module text.
 *
 * Written as one template rather than assembled from fragments: what this
 * emits is code a person will read in a stack trace and in a diff of their own
 * repository, and code that reads as though someone wrote it is code they can
 * follow when it is the thing that broke.
 *
 * ── One mount is its own shape ────────────────────────────────────────────
 * A page with a single resumed mount gets the module a person would have
 * written for that page: the selector at the one site that queries it, the one
 * element in a `const`, no keyed table and no loop over a list of one. The
 * table and the loop are what N mounts need, and a consumer with one mount
 * should not carry the generality that serves the other case — this module is
 * shipped code, and every line of it is bytes behind the first interaction.
 *
 * The two shapes are the same protocol, in the same order, reaching the same
 * modules: claim the served element (or build it from its template artifact
 * when the capture is what is running), save the caret, detach before the root
 * is cleared, offer, render, restore.
 */
function emit(input: EmitInput): string {
  const { render, glueNames, claims, carryFocus } = input;
  const globs = input.templateGlobs.map((glob) => JSON.stringify(glob)).join(', ');
  const only = claims.length === 1 ? claims[0]! : undefined;

  const claimRows = claims
    .map(
      (mount) =>
        `  { artifact: ${JSON.stringify(mount.artifact)}, ` +
        `selector: ${quote(`[${RESUME_ATTRIBUTE}="${mount.artifact}"]`)} },`,
    )
    .join('\n');

  const rootDefault =
    input.rootSelector === undefined
      ? ''
      : ` = document.querySelector<HTMLElement>(${JSON.stringify(input.rootSelector)})!`;

  const focusDeclarations = carryFocus
    ? `
interface SavedFocus {
  element: HTMLElement;
  start: number | null;
  end: number | null;
}

/** The caret, read while the node is still the focused one. */
function saveFocus(claimed: ${only === undefined ? 'HTMLElement[]' : 'HTMLElement'}): SavedFocus | null {
  const active = document.activeElement as HTMLElement | null;
  if (!active || !${
    only === undefined
      ? 'claimed.some((element) => element.contains(active))'
      : 'claimed.contains(active)'
  }) return null;

  const field = active as Partial<HTMLInputElement>;
  if (typeof field.setSelectionRange !== "function") return { element: active, start: null, end: null };
  try {
    return { element: active, start: field.selectionStart ?? null, end: field.selectionEnd ?? null };
  } catch {
    // Selection is not readable on every input type, and losing it is not a
    // reason to lose the focus as well.
    return { element: active, start: null, end: null };
  }
}

function restoreFocus(saved: SavedFocus | null): void {
  if (!saved || !saved.element.isConnected) return;
  saved.element.focus();
  if (saved.start === null) return;
  const field = saved.element as Partial<HTMLInputElement>;
  try {
    field.setSelectionRange?.(saved.start, saved.end ?? saved.start);
  } catch {
    // Same as above: a restored focus without a restored caret is still the
    // better of the two outcomes.
  }
}
`
    : '';

  const saveCall = carryFocus ? '  const focus = saveFocus(claimed);\n\n' : '';
  const restoreCall = carryFocus ? '\n  restoreFocus(focus);\n' : '\n';

  const templatesDoc =
    only === undefined
      ? `/**
 * The template artifacts of this page's resumed mounts, eager *in this chunk*
 * and nowhere else.`
      : `/**
 * The template artifact of this page's resumed mount, eager *in this chunk*
 * and nowhere else.`;

  const lookup =
    only === undefined
      ? `
function templateHtml(artifact: string): string {
  const suffix = \`/\${artifact}/template.js\`;
  for (const [path, module] of Object.entries(TEMPLATES)) {
    if (path.endsWith(suffix)) return module.html;
  }
  throw new Error(\`resume: this build emitted no template artifact for \${artifact}\`);
}
`
      : `
/**
 * The one artifact the glob above names.
 *
 * One mount is one template, so there is no key to look anything up by: the
 * glob's single entry is the answer.
 */
function templateHtml(): string {
  const template = Object.values(TEMPLATES).at(0);
  if (template === undefined) {
    throw new Error(${JSON.stringify(
      `resume: this build emitted no template artifact for ${only.artifact}`,
    )});
  }
  return template.html;
}
`;

  const claimTable =
    only === undefined
      ? `
/** Every mount this page resumed: the artifact it carries, and how it is found in the served markup. */
const CLAIMED = [
${claimRows}
] as const;
`
      : '';

  const swap =
    only === undefined
      ? `  // The served mounts, or — for the capture that produces the served page —
  // the template artifacts the capture is about to prove are in it.
  const claimed = CLAIMED.map(
    (mount) =>
      root.querySelector<HTMLElement>(mount.selector) ?? ${glueNames.createMount}(templateHtml(mount.artifact)),
  );

${saveCall}  // Detached first, so clearing the root cannot take them: these elements are
  // what the new tree is required to reuse.
  for (const element of claimed) element.remove();
  root.replaceChildren();
  for (const element of claimed) ${glueNames.offerClaim}(element);
`
      : `  // The served mount, or — for the capture that produces the served page —
  // the template artifact the capture is about to prove is in it.
  const claimed =
    root.querySelector<HTMLElement>(${quote(`[${RESUME_ATTRIBUTE}="${only.artifact}"]`)}) ??
    ${glueNames.createMount}(templateHtml());

${saveCall}  // Detached first, so clearing the root cannot take it: this element is what
  // the new tree is required to reuse.
  claimed.remove();
  root.replaceChildren();
  ${glueNames.offerClaim}(claimed);
`;

  return `${banner(input)}
import { ${render.named} } from ${JSON.stringify(render.module)};

import { ${input.policy.entryComponent} } from ${JSON.stringify(input.entrySpecifier)};
import { ${glueNames.createMount}, ${glueNames.offerClaim} } from ${JSON.stringify(input.glueSpecifier)};

${templatesDoc}
 *
 * The shipped page never reaches this glob: it finds the markup in the
 * document, where the build inlined it. The build-time capture is the one
 * caller — it runs this module against a document that has no shell in it yet,
 * because producing the shell is what the run is for.
 */
const TEMPLATES = import.meta.glob<{ html: string; root: string }>([${globs}], {
  eager: true,
});
${claimTable}${lookup}${focusDeclarations}
/**
 * Renders the group into \`root\`, claiming ${only === undefined ? 'each' : 'the'} resumed element.
 *
 * Called once per page — the loader that imports this module holds the single
 * promise that guarantees it. Returns the render's disposer, which is what a
 * test (and the build-time capture) uses to tear the page down again.
 */
export function execute(root: HTMLElement${rootDefault}): () => void {
${swap}
  const dispose = ${render.named}(${input.policy.entryComponent} as never, root);
${restoreCall}  return dispose;
}
`;
}

/** Provenance, and what the module is for, in the words the page's own configuration gives it. */
function banner(input: EmitInput): string {
  const names = input.claims.map((mount) => mount.artifact).join(', ');
  return (
    `// Generated by unplugin-solid-resumability for page ${JSON.stringify(input.page.id)}. Do not edit.\n` +
    '//\n' +
    '// The deferral group of this page: one chunk, one import, one execution.\n' +
    '// Every static import below is a byte that is not on the wire until the\n' +
    '// first interaction asks for it.\n' +
    '//\n' +
    `// What execution does is render-and-replace: ${names} — served markup,\n` +
    '// delegated listeners, whatever the user has typed in — is detached before\n' +
    `// the root is cleared and handed to \`${input.policy.entryComponent}\`'s substituted mount point, so\n` +
    '// the render inserts those same nodes rather than copies of them.\n'
  );
}

/**
 * The prerender stage: a page's first paint, captured from the build's own
 * output and inlined into the document it belongs to.
 *
 * What a resumable page serves is markup nothing is asked to claim. There is no
 * hydration pass to feed and no framework in the eager bundle to feed it, so
 * the markup has to be *right* — the same bytes the group will produce when it
 * finally runs, at the same state. The only thing that can produce those bytes
 * is the group itself, so this stage runs it: the built chunk, in a headless
 * document, snapshotted at the synchronous first paint.
 *
 * ── Why this runs after the build and not inside it ───────────────────────
 * The chunk has to exist on disk first. That is the whole reason the trigger is
 * `closeBundle` rather than anything earlier: what is captured must be the code
 * a browser will run, minified and chunked exactly as shipped, not the source it
 * was built from. A capture of the pre-build code would agree with the served
 * page right up until the day a bundler transform changed one byte of markup.
 *
 * ── What is proved before a byte is written ───────────────────────────────
 *   determinism   Every capture runs in a process of its own — fresh module
 *                 registry, fresh document, fresh store — and they must be
 *                 byte-identical. Separate processes rather than repeated calls
 *                 because a page's store registry is entitled to refuse two
 *                 live stores under one identity, and that refusal is the same
 *                 invariant that makes the swap sound; the capture does not get
 *                 an exemption from it.
 *   keys          Every item of every keyed region the paint carries states its
 *                 key. A resumed dispatch from inside a list is resolved by the
 *                 key its item's element carries and by nothing else, so an
 *                 unkeyed item is markup the resume path can only address by
 *                 POSITION — the one failure a key exists to prevent. The build
 *                 that paints the items is the build that owes them, which is
 *                 why the obligation is discharged here rather than left to a
 *                 refusal on the served page.
 *   templates     Each resumed mount's emitted markup must appear in the
 *                 snapshot verbatim. A page whose eager bundle ships no
 *                 template module carries that markup in the document instead,
 *                 and the byte check for it therefore belongs to the build that
 *                 did the inlining. This is that check.
 *   shape         The substrings the page says its first paint contains. Stated
 *                 by the consumer, because what a first paint looks like is a
 *                 fact about their application and a guess here would be a
 *                 check that passes for the wrong reason.
 *
 * ── Pure body, bundler-specific trigger ───────────────────────────────────
 * `prerenderPages` reads its inputs from an object and touches only the
 * directories it is handed. It is exported from `./node`, so a bundler with no
 * hook to hang it on loses the automation and keeps the capability: the same
 * call, run as a documented post-build step.
 */

import { execFileSync } from 'node:child_process';
import { existsSync, readFileSync, writeFileSync } from 'node:fs';
import { pathToFileURL } from 'node:url';
import { basename, join, relative } from 'pathe';
import type { UnpluginOptions } from 'unplugin';

import { locate } from '../../../src/resume/locate.ts';
import { componentRootIn, emptyElementHtml, rewritePageHtml } from '../html.ts';
import { readTemplate as readEmittedTemplate } from '../node.ts';
import { resolveUnder } from '../options.ts';
import type { ResolvedMount, ResolvedOptions, ResolvedPage } from '../types.ts';
import {
  CAPTURE_FLAG,
  CAPTURE_MODULE_PATH,
  CAPTURE_PAYLOAD_MARK,
  parseCapturedMarkup,
  type CaptureRequest,
} from './capture.ts';

/** Every shape this stage declines to capture, or declines to trust. */
export type PrerenderRefusalName =
  | 'PrerenderNotDeclared'
  | 'PrerenderGroupUndeclared'
  | 'RootSelectorUndeclared'
  | 'CaptureCountInvalid'
  | 'BuildManifestMissing'
  | 'GroupChunkAmbiguous'
  | 'GroupChunkNotDeferred'
  | 'CaptureFailed'
  | 'CaptureNotDeterministic'
  | 'CaptureEmpty'
  | 'RegionItemKeyMissing'
  | 'TemplateNotVerbatim'
  | 'ExpectedMarkupMissing'
  | 'CaptureBindingLocatorMissing'
  | 'PageDocumentMissing';

/**
 * A page this stage will not serve a captured paint for.
 *
 * `name` is the refusal's own name rather than the class's, so a caller can
 * branch on which rule fired without matching on prose that may be reworded.
 */
export class PrerenderError extends Error {
  readonly page: ResolvedPage;

  constructor(name: PrerenderRefusalName, message: string, page: ResolvedPage) {
    super(message);
    this.name = name;
    this.page = page;
  }
}

/** One component's emitted markup, however the caller gets hold of it. */
export type TemplateReader = (
  artifactRoot: string,
  ref: { artifact: string },
) => Promise<{ html: string }>;

/** Everything the stage is handed. Absolute paths in, no discovery, no guessing. */
export interface PrerenderInput {
  /** The build output directory: where the built chunks and the build manifest are. */
  distDir: string;
  /** Project root. What the build manifest's keys — and a page's declared paths — are relative to. */
  root: string;
  /** The pages. Only those declaring a prerender policy are captured. */
  pages: ResolvedPage[];
  /** The declared mounts. The ones on a captured page supply the template check. */
  mounts: ResolvedMount[];
  /** Where the pass emitted its artifacts. */
  artifactDir: string;
  /**
   * Where the built documents are read from and written back to. Defaults to
   * `distDir`, and exists so a caller can prove the capture against a shipped
   * build without writing into it.
   */
  htmlDir?: string;
  /** The build manifest, relative to `distDir`. Defaults to Vite's location. */
  manifest?: string;
  /** How a component's emitted markup is read. Defaults to this package's own reader. */
  readTemplate?: TemplateReader;
  /** Where the per-page lines go. Defaults to stdout. */
  log?: (line: string) => void;
}

/** One captured page: what was captured, from what, and where it went. */
export interface PrerenderedPage {
  page: ResolvedPage;
  /** The captured markup, exactly as inlined. */
  html: string;
  bytes: number;
  /** The built chunk the capture ran. */
  chunkPath: string;
  /** The document the shell was written into. */
  documentPath: string;
  /** How many independent captures agreed on these bytes. */
  captures: number;
}

export interface PrerenderReport {
  pages: PrerenderedPage[];
}

/** Where a Vite build writes its manifest, which is the one convention worth a default. */
const DEFAULT_MANIFEST = '.vite/manifest.json';

/** The export the generated group module renders through, when a page names no other. */
const DEFAULT_EXECUTE_EXPORT = 'execute';

/** How many independent captures have to agree, when a page asks for no number. */
const DEFAULT_CAPTURES = 2;

/** One chunk, as a build manifest describes it. Structural: no bundler's types are imported. */
interface ManifestChunk {
  file: string;
  src?: string;
  isDynamicEntry?: boolean;
}

/**
 * Captures every page that declared a prerender policy, and inlines each one.
 *
 * Sequential on purpose. Captures are child processes running a whole
 * application's chunk, and a page that fails should fail while the log still
 * reads as the story of one page.
 */
export async function prerenderPages(input: PrerenderInput): Promise<PrerenderReport> {
  const log = input.log ?? ((line: string) => console.log(line));
  const pages: PrerenderedPage[] = [];

  for (const page of input.pages) {
    if (page.prerender === false) continue;

    const captured = await prerenderPage(input, page);
    pages.push(captured);

    log(
      `prerender    ${page.id} (${captured.bytes} B, ${captured.captures} captures agreed) -> ` +
        `${relative(input.root, captured.documentPath)}`,
    );
  }

  return { pages };
}

/**
 * One page, start to finish, in the order the failures matter in.
 *
 * Written as one function rather than split by step because the steps only make
 * sense as a sequence: find the chunk, run it twice, prove what came out, and
 * only then touch a file. Nothing is written until every check has passed, so a
 * failed capture leaves the build's output exactly as the bundler left it.
 */
async function prerenderPage(input: PrerenderInput, page: ResolvedPage): Promise<PrerenderedPage> {
  const policy = page.prerender;
  if (policy === false) {
    throw new PrerenderError(
      'PrerenderNotDeclared',
      `page ${JSON.stringify(page.id)} declares no prerender policy, so there is nothing to ` +
        'capture. A page served without a first paint in it is a page that paints when its ' +
        'group arrives, which is a different design rather than a broken one.',
      page,
    );
  }

  if (page.group === false) {
    throw new PrerenderError(
      'PrerenderGroupUndeclared',
      `page ${JSON.stringify(page.id)} declares a prerender policy but no group. Capturing a ` +
        "page means running its group module; with no group there is nothing to run, and the " +
        'capture would report an empty shell as a success.',
      page,
    );
  }

  const rootSelector = policy.rootSelector;
  if (rootSelector === undefined) {
    throw new PrerenderError(
      'RootSelectorUndeclared',
      `page ${JSON.stringify(page.id)} declares a prerender policy with no \`rootSelector\`. ` +
        'Which element the captured paint is rendered into and inlined back into is a fact about ' +
        'your document; guessing one would either capture nothing or fill the wrong element.',
      page,
    );
  }

  const captures = policy.captures ?? DEFAULT_CAPTURES;
  if (!Number.isInteger(captures) || captures < 1) {
    throw new PrerenderError(
      'CaptureCountInvalid',
      `page ${JSON.stringify(page.id)} asks for ${captures} captures. It takes at least one ` +
        'capture to have markup at all, and at least two for the agreement between them to mean ' +
        'the render is deterministic.',
      page,
    );
  }

  const chunkPath = groupChunkPath(input, page, page.group.moduleId);

  const request: CaptureRequest = {
    chunkPath,
    documentHtml: captureDocument(rootSelector),
    rootSelector,
    execute: policy.execute ?? DEFAULT_EXECUTE_EXPORT,
  };

  const taken: string[] = [];
  for (let attempt = 0; attempt < captures; attempt += 1) {
    taken.push(captureInChildProcess(request, page));
  }

  const shell = taken[0]!;
  for (const [index, other] of taken.entries()) {
    if (other === shell) continue;
    throw new PrerenderError(
      'CaptureNotDeterministic',
      `captures 1 and ${index + 1} of page ${JSON.stringify(page.id)} differ, so what the page ` +
        'renders at first paint depends on something other than the code. The served shell would ' +
        `be one of two paints and the swap would show.\n${firstDifference(shell, other)}`,
      page,
    );
  }

  if (shell.trim() === '') {
    throw new PrerenderError(
      'CaptureEmpty',
      `page ${JSON.stringify(page.id)} captured empty: its group rendered nothing at first ` +
        'paint. Inlining that would ship a document whose root is as blank as the one the ' +
        'bundler produced, with a build that claimed otherwise.',
      page,
    );
  }

  // Beside the agreement, and before anything is said about the template: these
  // bytes are the page's paint rather than one of two paints, and the first
  // thing asked of them is whether the lists in them can be addressed at all.
  await assertRegionKeys(input, page, shell);

  if (policy.requireTemplateVerbatim ?? true) {
    const readTemplate = input.readTemplate ?? readEmittedTemplate;
    for (const mount of input.mounts) {
      if (mount.page !== page.id) continue;
      const { html: template } = await readTemplate(input.artifactDir, mount);
      const measured = await measuredBindingsOf(input, mount);

      // A hole-free template IS a substring of the paint, byte for byte. That is
      // the strongest thing that can be said about it, so it stays what is said.
      if (measured.length === 0) {
        if (shell.includes(template)) continue;
        throw new PrerenderError(
          'TemplateNotVerbatim',
          `the captured paint of page ${JSON.stringify(page.id)} does not contain ` +
            `${JSON.stringify(mount.artifact)}'s emitted markup verbatim, so the markup the ` +
            'resumer\'s locators address would not be the markup that is served.\n' +
            `  emitted:  ${template}\n  captured: ${shell}`,
          page,
        );
      }

      // A template with a measured binding in it cannot be a substring of the
      // paint that fills it: the build emitted an empty text exactly where the
      // capture is about to supply one. What is checkable is everything ELSE —
      // the template cut at its holes, each piece appearing in the paint, in
      // order. Every byte the build wrote is still verified; the only bytes
      // excused are the ones the build openly declined to write.
      const segments = templateSegments(template, measured);
      const missing = segments === null ? 0 : firstSegmentNotFound(shell, segments);
      if (segments !== null && missing < 0) continue;

      throw new PrerenderError(
        'TemplateNotVerbatim',
        `the captured paint of page ${JSON.stringify(page.id)} does not carry ` +
          `${JSON.stringify(mount.artifact)}'s emitted markup around its ${measured.length} ` +
          'measured binding(s), so the markup the resumer\'s locators address would not be the ' +
          'markup that is served.\n' +
          (segments === null
            ? '  the template could not be cut at its holes: a measured binding names a locator ' +
              'the emitted markup does not address.\n'
            : `  first piece missing: ${JSON.stringify(segments[missing])}\n`) +
          `  emitted:  ${template}\n  captured: ${shell}`,
        page,
      );
    }
  }

  for (const expected of policy.expectMarkup ?? []) {
    if (shell.includes(expected)) continue;
    throw new PrerenderError(
      'ExpectedMarkupMissing',
      `the captured paint of page ${JSON.stringify(page.id)} does not contain ` +
        `${JSON.stringify(expected)}, which this page states its first paint carries. Either the ` +
        'capture caught a state that is not the first paint, or the paint changed and the ' +
        `expectation has not.\n  captured: ${shell}`,
      page,
    );
  }

  // Measured last of the checks and first of the writes: every capture-sourced
  // binding takes its text from THESE bytes, which the agreement above already
  // proved are the page's paint rather than one of two paints.
  await measureCapturedBindings(input, page, shell);

  const documentPath = join(input.htmlDir ?? input.distDir, basename(page.html));
  if (!existsSync(documentPath)) {
    throw new PrerenderError(
      'PageDocumentMissing',
      `page ${JSON.stringify(page.id)} has no built document at ${documentPath}. The capture ` +
        'succeeded and has nowhere to go; a built page is looked for by its file name under the ' +
        'output directory.',
      page,
    );
  }

  const before = readFileSync(documentPath, 'utf8');
  const after = rewritePageHtml(before, [
    { kind: 'inline-shell', selector: rootSelector, html: shell },
  ]);
  writeFileSync(documentPath, after, 'utf8');

  return {
    page,
    html: shell,
    bytes: Buffer.byteLength(shell),
    chunkPath,
    documentPath,
    captures,
  };
}


/**
 * A binding whose text is measured rather than derived, as its artifact states
 * it. A derivation reaching into a context store has no build-time answer — the
 * store does not exist until the page runs — so the pass emits an empty text and
 * says where the real one comes from.
 */
interface MeasuredBinding {
  id: string;
  locator: string;
}

/**
 * A keyed region, as far as a captured paint is concerned: where its items are,
 * and what an item says to name itself.
 *
 * The rest of the record — the item template, the projection, the item's own
 * bindings and wiring — is the resume path's business. What a build owes is the
 * key, on every item it painted.
 */
interface KeyedRegion {
  id: string;
  container: string;
  keyAttribute: string;
}

/**
 * Every item of every keyed region this paint carries states its key, or the
 * build stops here.
 *
 * The region is found by ADDRESSING it, exactly as the resumer will: the
 * component's root is identified out of the whole page, and the region's own
 * container locator is walked from it. A region the paint does not carry — a
 * list whose guard was recorded absent, or a container the emitted markup never
 * addressed — has no items and is passed over; a region the paint DOES carry is
 * held to every child of that container, because the runtime calls every one of
 * them an item.
 *
 * Vacuous for a page with no list, and deliberately so. It is the populated
 * capture this exists for: a build free to paint items it did not key is a build
 * that can serve a list the resume path could only address by position.
 */
async function assertRegionKeys(
  input: PrerenderInput,
  page: ResolvedPage,
  shell: string,
): Promise<void> {
  const readTemplate = input.readTemplate ?? readEmittedTemplate;

  for (const mount of input.mounts) {
    if (mount.page !== page.id) continue;

    const regions = await keyedRegionsOf(input, mount);
    if (regions.length === 0) continue;

    const measured = await measuredBindingsOf(input, mount);
    const { html: template } = await readTemplate(input.artifactDir, mount);
    const parsed = parseCapturedMarkup(shell);
    try {
      // Nothing in the paint is this component: that is the verbatim check's
      // sentence to pass, and it is about to be asked. Keys are a claim about a
      // list this component painted, and there is no such list here.
      const root = componentRootFor(parsed.container, template, measured, regions);
      if (root === null) continue;

      for (const region of regions) {
        let container: Element;
        try {
          container = locate(root, region.container);
        } catch {
          continue; // the paint carries no such container, so it carries no items
        }

        const unkeyed = [...container.children].filter(
          (child) => !child.hasAttribute(region.keyAttribute),
        );
        if (unkeyed.length === 0) continue;

        throw new PrerenderError(
          'RegionItemKeyMissing',
          `the captured paint of page ${JSON.stringify(page.id)} carries ${unkeyed.length} item(s) ` +
            `of region ${JSON.stringify(region.id)} — ${JSON.stringify(mount.artifact)} at ` +
            `${JSON.stringify(region.container)} — with no ${region.keyAttribute} attribute. A ` +
            'resumed dispatch from inside a list is resolved by the key its item carries and by ' +
            'nothing else, so an unkeyed item could only be addressed by its POSITION among its ' +
            'siblings — which is the failure the key exists to prevent. The build that painted ' +
            'the items is the build that owes them.\n' +
            `  first unkeyed item: ${unkeyed[0]!.outerHTML}\n  captured: ${shell}`,
          page,
        );
      }
    } finally {
      parsed.close();
    }
  }
}

/**
 * Writes each capture-sourced binding's text into its artifact, read out of the
 * paint this page just captured.
 *
 * The whole soundness of the move is the ordering: the captures agreed byte for
 * byte BEFORE this runs, so the text taken here is a property of the code rather
 * than of one of two paints. Nothing is derived, folded or guessed — the element
 * at the binding's own locator is read, and what it says is what the artifact
 * gets.
 *
 * The component's root is found rather than assumed. A mount's artifacts are
 * addressed by locators from that root, and the shell is a whole page, so the
 * root is identified by the one thing that identifies it: the emitted template,
 * which is this markup with exactly the measured texts taken out. A candidate
 * matches when clearing those texts on a copy reproduces the emitted bytes.
 * Nothing matching is `CaptureBindingLocatorMissing` — the alternative would be
 * measuring some other element that happened to be shaped alike.
 */
async function measureCapturedBindings(
  input: PrerenderInput,
  page: ResolvedPage,
  shell: string,
): Promise<void> {
  const readTemplate = input.readTemplate ?? readEmittedTemplate;

  for (const mount of input.mounts) {
    if (mount.page !== page.id) continue;

    const structurePath = join(input.artifactDir, mount.artifact, 'structure.js');
    const measured = await measuredBindingsOf(input, mount);
    if (measured.length === 0) continue;

    const { html: template } = await readTemplate(input.artifactDir, mount);
    const regions = await keyedRegionsOf(input, mount);
    const parsed = parseCapturedMarkup(shell);
    let texts: Map<string, string>;
    try {
      const root = componentRootFor(parsed.container, template, measured, regions);
      if (root === null) {
        throw new PrerenderError(
          'CaptureBindingLocatorMissing',
          `page ${JSON.stringify(page.id)} carries ${measured.length} binding(s) of ` +
            `${JSON.stringify(mount.artifact)} whose text is measured from the capture, and no ` +
            'element of the captured paint is that component: clearing those texts on a copy of ' +
            'each candidate never reproduced the emitted template. The measured text would be ' +
            `some other element's.\n  emitted:  ${template}\n  captured: ${shell}`,
          page,
        );
      }
      texts = new Map(measured.map((binding) => [binding.id, locate(root, binding.locator).textContent ?? '']));
    } finally {
      parsed.close();
    }

    // One rewrite, after every binding read: a half-measured artifact would be
    // worse than an unmeasured one.
    let source = readFileSync(structurePath, 'utf8');
    for (const [id, text] of texts) {
      const anchor = new RegExp(`(id: ${JSON.stringify(id)},[\\s\\S]*?initialText: )"[^"]*"`);
      if (!anchor.test(source)) {
        throw new PrerenderError(
          'CaptureBindingLocatorMissing',
          `binding ${JSON.stringify(id)} of ${JSON.stringify(mount.artifact)} says its text is ` +
            'measured, but its emitted `structure.js` has no `initialText` to write it into. The ' +
            'artifact and the module that reads it disagree about what was emitted.',
          page,
        );
      }
      source = source.replace(anchor, `$1${JSON.stringify(text)}`);
    }
    writeFileSync(structurePath, source, 'utf8');
  }
}

/**
 * What the emitted template says of itself, with its holes taken out: the bytes
 * either side of every measured binding's text, in order.
 *
 * The holes are found by ADDRESSING them, not by parsing for them — each
 * measured binding names its own locator, and that locator is the one the
 * resumer will use. Marking through the same address is what makes this a check
 * on the same holes rather than on ones that look alike. `null` says the
 * template could not be cut, which is a refusal rather than a pass: a measured
 * binding whose locator does not address anything in its own component's markup
 * is an artifact set that disagrees with itself.
 */
function templateSegments(template: string, measured: MeasuredBinding[]): string[] | null {
  const parsed = parseCapturedMarkup(template);
  try {
    const root = parsed.container.firstElementChild;
    if (root === null || parsed.container.children.length !== 1) return null;

    for (const binding of measured) {
      try {
        locate(root, binding.locator).textContent = HOLE_MARK;
      } catch {
        return null;
      }
    }

    const marked = root.outerHTML;
    if (!marked.includes(HOLE_MARK_SERIALIZED)) return null;
    return marked.split(HOLE_MARK_SERIALIZED);
  } finally {
    parsed.close();
  }
}

/**
 * Where a hole is, written as text so the serializer escapes it into something
 * a template could not plausibly contain. `<` and `>` cannot survive as
 * themselves in a text node, so what comes back out is the entity form below —
 * fixed, and checked for rather than assumed.
 */
const HOLE_MARK = '<<unplugin-solid-resumability:hole>>';
const HOLE_MARK_SERIALIZED = '&lt;&lt;unplugin-solid-resumability:hole&gt;&gt;';

/**
 * The index of the first segment the paint does not carry after the one before
 * it, or -1 when every one of them is there, in order.
 *
 * Empty segments are skipped rather than searched for: a hole at either end of
 * the template, or two holes with nothing between them, produces one, and
 * "contains the empty string" is not a check.
 */
function firstSegmentNotFound(shell: string, segments: string[]): number {
  let at = 0;
  for (const [index, segment] of segments.entries()) {
    if (segment === '') continue;
    const found = shell.indexOf(segment, at);
    if (found === -1) return index;
    at = found + segment.length;
  }
  return -1;
}

/**
 * The bindings of one mount whose text the artifacts say a capture owes, read
 * out of the emitted `structure.js`.
 *
 * Asked twice per mount, on purpose: once to know how to check the template, and
 * once to fill it in. Reading the artifact both times rather than passing a list
 * between the two keeps the answer sourced from the same place the resume path
 * reads it from.
 */
async function measuredBindingsOf(
  input: PrerenderInput,
  mount: ResolvedMount,
): Promise<MeasuredBinding[]> {
  const structurePath = join(input.artifactDir, mount.artifact, 'structure.js');
  // A mount the pass refused has no artifacts, and a page may carry one.
  if (!existsSync(structurePath)) return [];

  const url = pathToFileURL(structurePath).href;
  const structure = (await import(`${url}?t=${Date.now()}`)) as {
    bindings?: Array<{ id: string; locator: string; initialTextFrom?: string }>;
  };
  return (structure.bindings ?? [])
    .filter((binding) => binding.initialTextFrom === 'capture')
    .map((binding) => ({ id: binding.id, locator: binding.locator }));
}

/**
 * The keyed regions of one mount, read out of the same emitted `structure.js`
 * the resume path reads them from. A component with no list says nothing about
 * them, and gets the empty answer every artifact emitted before regions existed
 * also gets.
 */
async function keyedRegionsOf(
  input: PrerenderInput,
  mount: ResolvedMount,
): Promise<KeyedRegion[]> {
  const structurePath = join(input.artifactDir, mount.artifact, 'structure.js');
  if (!existsSync(structurePath)) return [];

  const url = pathToFileURL(structurePath).href;
  const structure = (await import(`${url}?t=${Date.now()}`)) as {
    keyedRegions?: KeyedRegion[];
  };
  return (structure.keyedRegions ?? []).map((region) => ({
    id: region.id,
    container: region.container,
    keyAttribute: region.keyAttribute,
  }));
}

/**
 * The element in `container` that is this template, or null.
 *
 * One line, and a deliberate one: the answer comes from the page rewriter's own
 * `componentRootIn`, which is the same question asked by the check on a mount
 * the DOCUMENT carries. A capture and a hand-authored page are two triggers for
 * one obligation — the markup a locator addresses is the markup that is served
 * — and a second implementation of "which of these elements is that component"
 * would be two answers waiting to disagree.
 */
function componentRootFor(
  container: Element,
  template: string,
  measured: MeasuredBinding[],
  regions: KeyedRegion[] = [],
): Element | null {
  return componentRootIn(container, template, {
    measured: measured.map((binding) => binding.locator),
    regions,
  });
}

/**
 * The built chunk of the page's group, refused unless the build made it exactly
 * one deferred chunk.
 *
 * Both halves of that are load-bearing. More than one chunk for the group means
 * the bundler split it, and a capture of one half would render a fraction of
 * the page; none means the group did not survive as its own module at all. And
 * a group that is not a dynamic entry has been folded into something the page
 * loads eagerly — the bytes this whole pipeline exists to keep off the wire
 * would be on it, and the capture would happily produce a correct-looking shell
 * for a page that had already lost.
 */
function groupChunkPath(input: PrerenderInput, page: ResolvedPage, moduleId: string): string {
  const manifestPath = join(input.distDir, input.manifest ?? DEFAULT_MANIFEST);
  if (!existsSync(manifestPath)) {
    throw new PrerenderError(
      'BuildManifestMissing',
      `the build wrote no manifest at ${manifestPath}, so which chunk the group of page ` +
        `${JSON.stringify(page.id)} became cannot be looked up. Capturing needs the built chunk; ` +
        'turn the manifest on, or say where it is with `manifest`.',
      page,
    );
  }

  // A manifest names a module the way the bundler's root sees it, which is what
  // a declared module id already is once it is made relative again.
  const source = relative(input.root, resolveUnder(input.root, moduleId));
  const manifest = JSON.parse(readFileSync(manifestPath, 'utf8')) as Record<string, ManifestChunk>;

  const found = Object.entries(manifest).filter(
    ([key, chunk]) => key === source || chunk.src === source,
  );

  if (found.length !== 1) {
    throw new PrerenderError(
      'GroupChunkAmbiguous',
      `the build has ${found.length} chunks for ${JSON.stringify(source)}, the group module of ` +
        `page ${JSON.stringify(page.id)}, and capturing needs exactly one. ` +
        (found.length === 0
          ? 'None means the group did not survive the build as a module of its own — check that ' +
            'it is reachable, and that nothing inlined it.'
          : 'More than one means the bundler split it, and a capture of one part would render a ' +
            'fraction of the page.'),
      page,
    );
  }

  const [, chunk] = found[0]!;
  if (chunk.isDynamicEntry !== true) {
    throw new PrerenderError(
      'GroupChunkNotDeferred',
      `${JSON.stringify(source)} is in the build, but not as a dynamic entry — so the group of ` +
        `page ${JSON.stringify(page.id)} is on the wire eagerly. That is the cost this pipeline ` +
        'exists to remove, and a captured first paint on top of it would hide the regression ' +
        'rather than report it.',
      page,
    );
  }

  return join(input.distDir, chunk.file);
}

/**
 * The document a capture renders into: the page's root element, empty, and
 * nothing else.
 *
 * Deliberately not the built page. The built page is what the capture is *for*,
 * and rendering into a copy of it would let markup the bundler put there leak
 * into the bytes that are then inlined back — the shell would grow a little
 * every build.
 */
function captureDocument(rootSelector: string): string {
  return `<!doctype html><html><head></head><body>${emptyElementHtml(rootSelector)}</body></html>`;
}

/**
 * One capture, in a process of its own.
 *
 * The child is this package's own capture module, run as a script: it carries a
 * branch that fires only when node was handed that file and this flag. Run
 * rather than imported because after bundling the module lives inside one of
 * the entry bundles under whatever export name the bundler chose, and a child
 * that had to import it by name would be a child that broke the day the bundler
 * renamed something.
 *
 * Standard error is inherited, so a page that throws says so in the build's own
 * log rather than inside an error about parsing.
 */
function captureInChildProcess(request: CaptureRequest, page: ResolvedPage): string {
  let printed: string;
  try {
    printed = execFileSync(
      process.execPath,
      [CAPTURE_MODULE_PATH, CAPTURE_FLAG, JSON.stringify(request)],
      { encoding: 'utf8', stdio: ['ignore', 'pipe', 'inherit'], maxBuffer: 64 * 1024 * 1024 },
    );
  } catch (cause) {
    throw new PrerenderError(
      'CaptureFailed',
      `running ${request.chunkPath} to capture page ${JSON.stringify(page.id)} failed. The ` +
        'chunk is the page as it will be served, so a chunk that cannot run in a headless ' +
        'document is a page that cannot be captured; what it threw is above this line. ' +
        `(${(cause as Error).message})`,
      page,
    );
  }

  // Whatever the page's own code wrote to standard output comes first; the
  // payload is what follows the last mark.
  const at = printed.lastIndexOf(CAPTURE_PAYLOAD_MARK);
  if (at === -1) {
    throw new PrerenderError(
      'CaptureFailed',
      `the capture of page ${JSON.stringify(page.id)} printed no markup. The child process ` +
        'exited without reporting, which means it never reached the end of the render.',
      page,
    );
  }

  return (JSON.parse(printed.slice(at + CAPTURE_PAYLOAD_MARK.length)) as { html: string }).html;
}

/** Where two strings first differ, with enough either side of it to read. */
function firstDifference(first: string, second: string): string {
  let at = 0;
  while (at < first.length && at < second.length && first[at] === second[at]) at += 1;
  const from = Math.max(0, at - 60);
  return (
    `at byte ${at}:\n` +
    `  first:  …${first.slice(from, at + 60)}…\n` +
    `  second: …${second.slice(from, at + 60)}…`
  );
}

/** What the trigger needs from the rest of the package, handed in rather than imported. */
export interface PrerenderContext {
  /** The options as they stand once the bundler has resolved its config. */
  options(): ResolvedOptions;
  /** How a component's emitted markup is read. */
  readTemplate?: TemplateReader;
}

/** How Vite states the two facts this trigger needs. Structural: no bundler's types are imported. */
export interface PrerenderBuildConfig {
  root?: string;
  command?: string;
  build?: { outDir?: string };
}

/**
 * The trigger: Vite's `closeBundle`, and the config hook that tells it where to
 * look.
 *
 * `closeBundle` because the capture runs the built chunk, and `closeBundle` is
 * the first moment every chunk is on disk. `configResolved` because the output
 * directory is the bundler's to decide and asking the consumer to declare it a
 * second time would be two places for one fact to drift apart.
 *
 * A dev server never gets here: there is no built chunk to run and no document
 * to write into. `transformIndexHtml` serves that workflow, and it serves it
 * with the page's real components rather than a captured stand-in.
 */
export function prerenderPlugin(context: PrerenderContext): UnpluginOptions {
  let distDir: string | undefined;
  let building = false;

  return {
    name: 'unplugin-solid-resumability:prerender',

    vite: {
      apply: 'build' as const,

      configResolved(config: PrerenderBuildConfig) {
        building = config.command === 'build';
        const root = config.root ?? process.cwd();
        distDir = resolveUnder(root, config.build?.outDir ?? 'dist');
      },

      async closeBundle() {
        if (!building || distDir === undefined) return;
        const options = context.options();
        if (!options.pages.some((page) => page.prerender !== false)) return;

        await prerenderPages({
          distDir,
          root: options.root,
          pages: options.pages,
          mounts: options.mounts,
          artifactDir: options.artifactDir,
          readTemplate: context.readTemplate,
        });
      },
    } as UnpluginOptions['vite'],
  };
}

/**
 * Substitution: the module a resumability compiler emits for a page.
 *
 * A component the pass proved does not need to ship. The rewritten module
 * carries the corpus module with its proven component's body gone and its
 * mount point replaced by an expression that publishes the live store and
 * claims the element already carrying the resumed component. Every other
 * component in the module is copied through byte for byte and still renders
 * the ordinary way.
 *
 * Three edits, all of them read off the analysis rather than found in the text:
 *
 *   1. REMOVAL. `ComponentSite.fn` is the function node; the top-level
 *      statement carrying it is the span that goes. Not stubbed, not renamed,
 *      not left for a minifier to maybe drop — the claim is that the component
 *      never runs, and the strongest form of that claim is that its body is not
 *      in the module.
 *
 *   2. THE MOUNT POINT. The unique `<Component />` element inside another
 *      component's returned markup becomes `{claim(useContext(Ctx))}` — an
 *      expression, not a component, because a substituted component would
 *      itself be a function the page executes. The argument is the component's
 *      own context read, reprinted from its own AST and evaluated at the same
 *      point in the same owner tree: that is what lets the page reach the LIVE
 *      store without one byte of the source module changing.
 *
 *   3. IMPORT RE-ROOTING. The rewritten module sits in the generated directory,
 *      so every relative specifier is recomputed from there to the file it
 *      already named. Bare specifiers are left alone.
 *
 * Everything this stage will not do, it refuses by name. A substituter that
 * guessed would emit a page that looks right and resumes the wrong element.
 */

import { mkdirSync, writeFileSync, readFileSync } from 'node:fs';
import { dirname, relative, resolve } from 'pathe';

import { contains, printExpression, unwrap, type Node } from '../../../src/comptime/ast.ts';
import { findComponents, type ComponentSite } from '../../../src/comptime/discover.ts';
import { loadProject } from '../../../src/comptime/project.ts';
import { useContextCalls } from '../../../src/comptime/stores.ts';
import type { Analysis, ProvableAnalysis } from '../../../src/comptime/types.ts';
import type {
  ResolvedMount,
  ResolvedOptions,
  SubstitutionEdit,
  SubstitutionResult,
} from '../types.ts';
import type { MountOutcome } from './analyze.ts';

/** Every shape this stage declines to rewrite. */
export type SubstitutionRefusalName =
  | 'SubstitutionNotDeclared'
  | 'ComponentNotDeclared'
  | 'ComponentNotModuleLocal'
  | 'UnprovableSubstitution'
  | 'MountSiteMissing'
  | 'MultipleMountSites'
  | 'MountElementNotBare'
  | 'ContextBindingUnreachable'
  | 'ComponentSurvivedRemoval';

/**
 * A module this stage will not rewrite.
 *
 * `name` is the refusal's own name rather than the class's, so a caller can
 * branch on which rule fired without matching on prose that may be reworded.
 */
export class SubstitutionError extends Error {
  readonly mount: ResolvedMount;

  constructor(name: SubstitutionRefusalName, message: string, mount: ResolvedMount) {
    super(message);
    this.name = name;
    this.mount = mount;
  }
}

export interface SubstituteStageOptions {
  /** Where the per-module lines go. Defaults to stdout. */
  log?: (line: string) => void;
}

export interface SubstituteReport {
  results: SubstitutionResult[];
}

/**
 * Rewrites every mount that declared a substitution and writes each result.
 *
 * Runs in the same pass as analyze and directly after it, because it consumes
 * that pass's verdicts and because the generated modules have to be real files
 * before module resolution begins.
 */
export function runSubstituteStage(
  options: ResolvedOptions,
  outcomes: MountOutcome[],
  stage: SubstituteStageOptions = {},
): SubstituteReport {
  const log = stage.log ?? ((line: string) => console.log(line));
  const results: SubstitutionResult[] = [];

  for (const outcome of outcomes) {
    if (outcome.mount.substitute === undefined) continue;

    const result = substituteModule(options, outcome.mount, outcome.analysis);
    mkdirSync(dirname(result.path), { recursive: true });
    writeFileSync(result.path, result.code, 'utf8');
    results.push(result);

    log(
      `substituted  ${outcome.mount.source} (${outcome.mount.component}) -> ` +
        `${relative(options.root, result.path)}`,
    );
  }

  return { results };
}

/**
 * The rewrite as a function of the source, so a test can run it without a
 * filesystem and the build and the tests cannot diverge.
 */
export function substituteModule(
  options: ResolvedOptions,
  mount: ResolvedMount,
  analysis: Analysis,
): SubstitutionResult {
  const substitution = mount.substitute;
  if (substitution === undefined) {
    throw new SubstitutionError(
      'SubstitutionNotDeclared',
      `mount ${JSON.stringify(mount.component)} has no \`substitute\` declaration, so there is ` +
        'nowhere to write a rewritten module and no glue to claim it with.',
      mount,
    );
  }

  const source = readFileSync(mount.sourcePath, 'utf8');
  const outPath = substitution.outPath;

  let edits: SubstitutionEdit[] = [];
  let refusal: SubstitutionError | undefined;
  try {
    edits = planEdits(options, mount, analysis, source, outPath);
  } catch (error) {
    // The escape hatch exists for exactly the shapes the analysis refuses, so
    // a refusal is what the consumer's transform is handed rather than what it
    // is denied the chance to answer.
    if (!(error instanceof SubstitutionError) || options.substitute.transform === undefined) throw error;
    refusal = error;
  }

  const transform = options.substitute.transform;
  if (transform !== undefined) {
    const code = transform({ source, path: mount.sourcePath, mount, outPath, analysis, edits, refusal });
    return { mount, path: outPath, code, edits, transformed: true };
  }

  const body = applyEdits(source, edits);
  survives(body, mount);

  const banner = substitution.banner ?? defaultBanner(mount);
  const claim = `import { ${substitution.helper} } from ${JSON.stringify(substitution.specifier)};`;
  const code = `${endsWithNewline(banner)}\n${claim}\n${body}`;

  return { mount, path: outPath, code, edits, transformed: false };
}

/**
 * The three edits, in source order. Computing them all before applying any is
 * what lets a consumer's transform see the whole rewrite rather than a
 * half-rewritten string.
 */
function planEdits(
  options: ResolvedOptions,
  mount: ResolvedMount,
  analysis: Analysis,
  source: string,
  outPath: string,
): SubstitutionEdit[] {
  const project = loadProject(mount.sourcePath, options.corpusRoot);
  const moduleInfo = project.entry;
  const sites = findComponents(moduleInfo);
  const site = sites.find((candidate) => candidate.name === mount.component) ?? null;

  const elements = mountElements(moduleInfo, mount.component);

  if (site === null) {
    // A component mounted here but declared elsewhere would need two modules
    // rewritten at once. Declined rather than half-supported.
    if (elements.length > 0) {
      throw new SubstitutionError(
        'ComponentNotModuleLocal',
        `${mount.source} mounts \`${mount.component}\` but does not declare it. Substitution ` +
          'rewrites one module: the component and its mount point have to live in the same ' +
          'file. Declare the mount against the module that owns the component, or supply ' +
          '`substitute.transform`.',
        mount,
      );
    }
    throw new SubstitutionError(
      'ComponentNotDeclared',
      `${mount.source} declares no module-scope component named \`${mount.component}\`. Found: ` +
        `${sites.map((candidate) => candidate.name).join(', ') || '(none)'}.`,
      mount,
    );
  }

  if (analysis.status !== 'provable') {
    throw new SubstitutionError(
      'UnprovableSubstitution',
      `\`${mount.component}\` in ${mount.source} classified fallback, so there are no artifacts ` +
        `to substitute to: ${analysis.reasons.map((reason) => reason.code).join(', ') || '(no reason given)'}. ` +
        'A component that still has to run is one this stage leaves alone.',
      mount,
    );
  }

  const element = uniqueMountElement(elements, site, sites, mount);

  const edits: SubstitutionEdit[] = [
    ...rerootedImports(moduleInfo, source, mount.sourcePath, outPath),
    removal(moduleInfo, site, source),
    {
      kind: 'replace-mount',
      start: element.start,
      end: element.end,
      text: claimExpression(moduleInfo, site, analysis, mount),
      note: `the mount point of \`${mount.component}\` claims its resumed element`,
    },
  ];

  return edits.sort((left, right) => left.start - right.start);
}

/** Every `<Component …>` element in the module, mount point or not. */
function mountElements(moduleInfo: { findAll(type: string): Node[] }, component: string): Node[] {
  return moduleInfo.findAll('JSXElement').filter((element: Node) => {
    const name = element.openingElement?.name;
    return name != null && name.type === 'JSXIdentifier' && name.name === component;
  });
}

/**
 * The one mount point, or a refusal.
 *
 * Uniqueness is the whole check: one set of artifacts describes one element,
 * so a component mounted twice has no single element the claim could take, and
 * taking the first would resume one of them and leave the other empty.
 */
function uniqueMountElement(
  elements: Node[],
  site: ComponentSite,
  sites: ComponentSite[],
  mount: ResolvedMount,
): Node {
  // A component that mounts itself is recursion, not a mount point.
  const outside = elements.filter((element) => !contains(site.fn, element));

  if (outside.length > 1) {
    throw new SubstitutionError(
      'MultipleMountSites',
      `${mount.source} mounts \`${mount.component}\` ${outside.length} times. One set of ` +
        'artifacts describes one element, so which of them the claim would take is not ' +
        'decidable. Mount it once, or supply `substitute.transform`.',
      mount,
    );
  }

  const element = outside[0];
  const parent =
    element === undefined
      ? undefined
      : sites.find((candidate) => candidate !== site && contains(candidate.returnArgument, element));

  if (element === undefined || parent === undefined) {
    throw new SubstitutionError(
      'MountSiteMissing',
      `${mount.source} declares \`${mount.component}\` but no other component in it returns a ` +
        '`<' + mount.component + ' />` element. There is nothing to replace, and removing the ' +
        'component alone would drop it from the page.',
      mount,
    );
  }

  const attributes = (element.openingElement?.attributes as Node[] | undefined) ?? [];
  const children = (element.children as Node[] | undefined) ?? [];
  if (attributes.length > 0 || children.length > 0) {
    throw new SubstitutionError(
      'MountElementNotBare',
      `the mount point of \`${mount.component}\` in ${mount.source} carries ` +
        `${attributes.length} prop(s) and ${children.length} child node(s). The artifacts model ` +
        'neither, so a resumed element cannot receive them. Move what it needs into the store, ' +
        'or supply `substitute.transform`.',
      mount,
    );
  }

  return element;
}

/**
 * The expression the mount point becomes.
 *
 * The argument is not invented: it is the component's own `useContext` call,
 * reprinted from the AST the pass already proved. The local name has to be the
 * name the analysis knows the context by, because that is the name the claim
 * is written with — an alias is a refusal rather than a guess.
 */
function claimExpression(
  moduleInfo: Node,
  site: ComponentSite,
  analysis: ProvableAnalysis,
  mount: ResolvedMount,
): string {
  const calls = useContextCalls(moduleInfo, site.fn);
  const args: string[] = [];

  for (const store of analysis.stores) {
    const call = calls.find((candidate: Node) => {
      const argument = unwrap(candidate.arguments[0]);
      return argument != null && argument.type === 'Identifier' && argument.name === store.context;
    });

    if (call === undefined) {
      const named = calls
        .map((candidate: Node) => unwrap(candidate.arguments[0])?.name)
        .filter((name: unknown) => typeof name === 'string');
      throw new SubstitutionError(
        'ContextBindingUnreachable',
        `\`${mount.component}\` reads the context \`${store.context}\` declared in ` +
          `${store.contextModule}, but ${mount.source} has no binding of that name — it reads ` +
          `${named.map((name: string) => `\`${name}\``).join(', ') || '(nothing)'} instead. The ` +
          'claim is written with the name the analysis knows, so import the context under its ' +
          'own name, or supply `substitute.transform`.',
        mount,
      );
    }

    args.push(printExpression(call));
  }

  return `{${mount.substitute!.helper}(${args.join(', ')})}`;
}

/**
 * The removal span: the whole top-level statement, so an exported component
 * does not leave its `export` behind.
 *
 * The blank lines either side collapse into one, which is what the module
 * would have looked like had the component never been written there.
 */
function removal(moduleInfo: Node, site: ComponentSite, source: string): SubstitutionEdit {
  const statement =
    (moduleInfo.ast.body as Node[]).find((candidate: Node) => contains(candidate, site.fn)) ?? site.fn;

  let start = statement.start;
  let end = statement.end;
  while (start > 0 && source.charCodeAt(start - 1) === 10) start -= 1;
  while (end < source.length && source.charCodeAt(end) === 10) end += 1;

  let text = '\n\n';
  if (start === 0) text = '';
  else if (end >= source.length) text = '\n';

  return { kind: 'remove-component', start, end, text, note: `\`${site.name}\` is not in the module` };
}

/**
 * Every relative specifier, recomputed from the generated directory to the
 * file it already named. Bare specifiers are somebody else's resolution and
 * are left exactly as written.
 */
function rerootedImports(
  moduleInfo: Node,
  source: string,
  sourcePath: string,
  outPath: string,
): SubstitutionEdit[] {
  const fromDir = dirname(outPath);
  const edits: SubstitutionEdit[] = [];

  for (const statement of moduleInfo.ast.body as Node[]) {
    const specifier = statement?.source;
    if (specifier == null || typeof specifier.value !== 'string') continue;
    if (!specifier.value.startsWith('.')) continue;

    const target = resolve(dirname(sourcePath), specifier.value);
    let rerooted = relative(fromDir, target);
    if (!rerooted.startsWith('.')) rerooted = `./${rerooted}`;

    // The delimiter is the author's, not this stage's.
    const quote = source[specifier.start] ?? '"';
    edits.push({
      kind: 'reroot-import',
      start: specifier.start,
      end: specifier.end,
      text: `${quote}${rerooted}${quote}`,
      note: `${specifier.value} is reached from the generated directory`,
    });
  }

  return edits;
}

/** Splices the edits into the source, last first so earlier spans stay valid. */
function applyEdits(source: string, edits: SubstitutionEdit[]): string {
  let out = source;
  for (const edit of [...edits].sort((left, right) => right.start - left.start)) {
    out = out.slice(0, edit.start) + edit.text + out.slice(edit.end);
  }
  return out;
}

/**
 * The claim this stage makes, checked against what it emitted: the component's
 * name does not occur in the rewritten code at all. Prose is not code, so the
 * consumer's banner is not part of what is checked.
 */
function survives(body: string, mount: ResolvedMount): void {
  const token = new RegExp(`\\b${mount.component.replace(/[^\w$]/g, '\\$&')}\\b`);
  if (!token.test(body)) return;

  throw new SubstitutionError(
    'ComponentSurvivedRemoval',
    `\`${mount.component}\` still occurs in the module rewritten from ${mount.source}. The ` +
      'removal cut a span that was not the whole component, or something else in the file ' +
      'names it.',
    mount,
  );
}

/** Provenance, and what the one edit was. Replaced wholesale by `substitute.banner`. */
function defaultBanner(mount: ResolvedMount): string {
  return (
    `// Generated by unplugin-solid-resumability from ${mount.source}. Do not edit.\n` +
    '//\n' +
    `// The module with ONE edit a resumability compiler would make: the mount\n` +
    `// point of \`${mount.component}\` — a component this pass proves — no longer renders a\n` +
    '// component. It publishes the live store and claims the element already\n' +
    `// carrying the resumed component, and \`${mount.component}\`'s body is not in this file\n` +
    '// at all. Every other component here is the source module, unchanged.\n'
  );
}

function endsWithNewline(text: string): string {
  return text.endsWith('\n') ? text : `${text}\n`;
}

/**
 * The whole configuration surface, declared in one place.
 *
 * The line every field sits on either side of: the consumer declares what only
 * they know, and the pass derives everything the analysis can reach. Verdicts,
 * group membership, removal spans, mount expressions, template bytes and the
 * chunking constraints are derived and never appear here. What appears here is
 * which components to prove, which pages carry them, and the policies that
 * decide how loudly to refuse.
 *
 * Types for stages that land in later slices are declared now, deliberately.
 * A surface that grows one field per slice teaches consumers that the shape is
 * provisional; a surface stated whole tells them where their config is going.
 */

import type { Analysis } from '../../src/comptime/types.ts';

/** The pass's verdict for one component, so a consumer's transform can be typed. */
export type ComptimeAnalysis = Analysis;

/** Everything the plugin is given. `mounts` is the only required field. */
export interface ResumabilityOptions {
  /** Project root. Defaults to the bundler's root, or the process cwd. */
  root?: string;
  /** What module paths are reported relative to. Defaults to `root`. */
  corpusRoot?: string;
  /** Where artifacts are emitted. Defaults to `<root>/artifacts`. */
  artifactDir?: string;
  /** Where generated modules are written. Defaults to `<root>/src/generated`. */
  generatedDir?: string;
  /** The components to prove and resume. */
  mounts: MountDeclaration[];
  /** The HTML entries that participate. */
  pages?: PageDeclaration[];
  policies?: ResumabilityPolicies;
  /**
   * Specifier the generated modules import the browser runtime through.
   * Defaults to this package's own `unplugin-solid-resumability/runtime`.
   *
   * Configurable because a project that consumes the runtime through an
   * installed copy pays for it in its own module graph — a workspace that
   * needs the runtime to resolve somewhere else says so here.
   */
  runtime?: string;
  /** For component shapes the analysis refuses. Not the road most travelled. */
  substitute?: { transform?: (context: SubstitutionContext) => string };
}

/** One component to prove, and where it is mounted. */
export interface MountDeclaration {
  /** Local binding name in `source`. */
  component: string;
  /** Root-relative module path. Read-only: the pass never writes to it. */
  source: string;
  /** Artifact directory name. Defaults to the key the pass derives from `(source, component)`. */
  artifact?: string;
  /** Which `PageDeclaration.id` this mount belongs to. */
  page?: string;
  /** Overrides `policies.expectProvable`. A fallback verdict then fails the build. */
  expectProvable?: boolean;
  /** Emit a rewritten copy of `source` with this component's mount point resumed. */
  substitute?: MountSubstitution;
}

/**
 * What a rewritten module needs that the analysis cannot reach: where it goes,
 * and the glue it calls. Everything else — the removal span, the mount
 * expression, the re-rooted specifiers — is derived.
 */
export interface MountSubstitution {
  /** Where the rewritten module is written. Relative paths land under `generatedDir`. */
  out: string;
  /** The glue the mount point calls to claim its resumed element. */
  claim: {
    /** Exported function name. Defaults to `claim` followed by the component's name. */
    helper?: string;
    /**
     * The module it is imported from: a root-relative path, re-rooted to the
     * generated directory, or a bare specifier, emitted as written.
     */
    module: string;
  };
  /** Prose the generated module opens with. Defaults to a provenance note. */
  banner?: string;
}

/** One HTML entry that participates, and what happens to it. */
export interface PageDeclaration {
  id: string;
  /** Root-relative HTML entry. */
  html: string;
  /** The entry-script swap: the classic module out, the resumable one in. */
  entry?: { from: string; to: string };
  /** Fill this page's declared mount points with their emitted templates. */
  inlineTemplates?: boolean;
  prerender?: PrerenderPolicy | false;
  group?: GroupPolicy | false;
  /**
   * Where this page's fallback branch is, so `policies.fallback: 'auto-omit'`
   * has something to omit. A page that declares none always carries whatever it
   * carries.
   */
  fallback?: PageFallback;
}

/**
 * The one thing about a fallback branch no analysis can reach: which module
 * holds it, and which specifier it reaches the ordinary renderer through.
 *
 * The branch itself is derived — a page is fully provable iff every mount
 * declared against it came back provable — but *where the branch is written* is
 * the consumer's own architecture. A plugin that went looking for
 * `import()` calls that smell like a renderer would be guessing at the one
 * decision it must not guess at.
 */
export interface PageFallback {
  /** Root-relative module carrying the dynamic import. */
  module: string;
  /** The specifier that import names, exactly as the module writes it. */
  specifier: string;
}

/** How a page is captured ahead of time. Consumed by the prerender stage. */
export interface PrerenderPolicy {
  /** CSS selector for the element the captured markup is inlined into. */
  rootSelector?: string;
  /** How many captures to take, each in its own process. Defaults to 2, and they must agree byte for byte. */
  captures?: number;
  /** Require the captured markup to carry each mount's emitted template verbatim. Defaults to true. */
  requireTemplateVerbatim?: boolean;
  /** Substrings the captured shell must contain. The shape assertions, stated by the consumer rather than guessed. */
  expectMarkup?: string[];
  /**
   * The export the built group chunk is rendered through. It takes the root
   * element and returns a disposer.
   *
   * Defaults to `execute`, which is what the generated group module exports —
   * declared here for a page whose group is hand-written and calls it something
   * else.
   */
  execute?: string;
}

/** How the deferred group module for a page is generated. */
export interface GroupPolicy {
  /** Where the generated group module is written. Relative paths are resolved against the root. */
  moduleId: string;
  /** The component the group renders. It has to be exported by one of this page's rewritten modules. */
  entryComponent: string;
  /** Carry focus and selection across the swap from resumed markup to rendered. Defaults to true. */
  carryFocus?: boolean;
  /** Members are derived from shared-state reachability; an override is an escape hatch. */
  members?: string[];
  /**
   * How the generated `execute` finds the element it renders into when its
   * caller names none. Defaults to the page's own `prerender.rootSelector`,
   * since a captured page already had to say where its markup goes; with
   * neither, the generated function takes its root as a required argument.
   */
  rootSelector?: string;
  /**
   * The glue the group calls: one function that builds a mount element from an
   * emitted template (the capture path only — a shipped page finds its mounts
   * in the document), and one that offers a live element to the substituted
   * mount point that claims it.
   *
   * `module` defaults to the module this page's substitution already names,
   * because the two halves of that protocol live together in every project
   * that has written it once.
   */
  glue?: { module?: string; createMount?: string; offerClaim?: string };
  /** The framework call the group renders through. Defaults to Solid's `render`. */
  render?: { module?: string; named?: string };
}

/** The refusals and the defaults, in one object so a project states its stance once. */
export interface ResumabilityPolicies {
  /** A declared mount that classifies fallback fails the build. Defaults to true. */
  expectProvable?: boolean;
  /**
   * When the deferred group is fetched. Defaults to `interaction`.
   * `idle` is refused by name: an idle prefetch spends the user's network on
   * work no one asked for, which is the whole cost this pipeline exists to
   * remove.
   */
  prefetch?: 'interaction' | 'none';
  /**
   * Whether a page always carries the fallback path. Defaults to `always`.
   *
   * `auto-omit` drops the branch from every page that declares one and is
   * FULLY PROVABLE — every mount declared against it came back provable. The
   * dynamic `import()` is rewritten out of the declaring module, so the
   * bundler emits no chunk for it at all: not a smaller chunk, not a stub, no
   * chunk. A page that is fully provable cannot reach that branch, and a branch
   * nothing can reach is bytes the build has no business emitting.
   *
   * Per page, never per project: a mixed page keeps its fallback under the same
   * policy, because its unprovable mounts still need the ordinary renderer.
   */
  fallback?: 'always' | 'auto-omit';
  /** Remove artifact directories no declared mount claims. Defaults to true. */
  pruneStaleArtifacts?: boolean;
  /** Apply the chunking constraints to the consumer's build config. Defaults to true. */
  chunking?: boolean;
}

/** One span of the source module, and what it becomes. */
export interface SubstitutionEdit {
  kind: 'remove-component' | 'replace-mount' | 'reroot-import';
  /** Byte span in the unmodified source. */
  start: number;
  end: number;
  /** What the span becomes. */
  text: string;
  /** What the edit is for, in one line. */
  note: string;
}

/** One rewritten module. `code` is what is written to `path`. */
export interface SubstitutionResult {
  mount: ResolvedMount;
  path: string;
  code: string;
  edits: SubstitutionEdit[];
  /** True when a consumer-supplied transform produced `code`. */
  transformed: boolean;
}

/**
 * What a consumer-supplied substitution transform is handed: the source, the
 * verdict the pass reached, and the edits this stage computed — including the
 * refusal, when the shape is one it declined, since that is the case the hatch
 * exists for. What it returns is written verbatim.
 */
export interface SubstitutionContext {
  /** The unmodified source of the module carrying the mount. */
  source: string;
  /** Absolute path of that module. */
  path: string;
  /** The mount being substituted. */
  mount: ResolvedMount;
  /** Where the rewritten module will be written. */
  outPath: string;
  /** The pass's verdict for this mount. */
  analysis: ComptimeAnalysis;
  /** The edits this stage computed, in source order. Empty when it refused. */
  edits: SubstitutionEdit[];
  /** Why this stage refused, when it did. */
  refusal?: Error;
}

/** A mount with every default filled in. What the stages actually read. */
export interface ResolvedMount {
  component: string;
  /** Root-relative, as declared. */
  source: string;
  /** Absolute path the pass reads. */
  sourcePath: string;
  artifact: string;
  page?: string;
  expectProvable: boolean;
  substitute?: ResolvedSubstitution;
}

/** A substitution with its paths absolute and its defaults filled in. */
export interface ResolvedSubstitution {
  /** Absolute path of the rewritten module. */
  outPath: string;
  /** The glue function the mount point calls. */
  helper: string;
  /** The specifier it is imported through, as the rewritten module will read it. */
  specifier: string;
  /**
   * Absolute path of the glue module, when the declaration named a file rather
   * than a bare specifier. Kept because a second generated module in a second
   * directory has to re-root the same module from where IT sits.
   */
  modulePath?: string;
  /** Consumer prose, when they wrote some. */
  banner?: string;
}

/** A page with every default filled in. */
export interface ResolvedPage {
  id: string;
  html: string;
  htmlPath: string;
  entry?: { from: string; to: string };
  inlineTemplates: boolean;
  prerender: PrerenderPolicy | false;
  group: GroupPolicy | false;
  fallback: ResolvedPageFallback | false;
}

/** A fallback branch with its module resolved to an absolute path. */
export interface ResolvedPageFallback {
  /** Root-relative, as declared. */
  module: string;
  /** Absolute path of the module carrying the branch. */
  modulePath: string;
  specifier: string;
}

/** Policies with every default filled in. */
export interface ResolvedPolicies {
  expectProvable: boolean;
  prefetch: 'interaction' | 'none';
  fallback: 'always' | 'auto-omit';
  pruneStaleArtifacts: boolean;
  chunking: boolean;
}

/** The options every stage is handed. Absolute paths, no optionals, no guessing. */
export interface ResolvedOptions {
  root: string;
  corpusRoot: string;
  artifactDir: string;
  generatedDir: string;
  mounts: ResolvedMount[];
  pages: ResolvedPage[];
  policies: ResolvedPolicies;
  runtime: string;
  substitute: { transform?: (context: SubstitutionContext) => string };
}

/** The Vite entry. The one bundler whose hooks can reach a dev server's HTML, which is why it is the reference target. */
import unplugin from './index.ts';

export default unplugin.vite;

/** The webpack entry. */
import unplugin from './index.ts';

export default unplugin.webpack;
